24	function playChime() {
25	  try {
26	    if (typeof window === "undefined") return;
27	    const AC = (window.AudioContext || (window as any).webkitAudioContext) as typeof AudioContext | undefined;
28	    if (!AC) return;
29	    if (!audioCtx) audioCtx = new AC();
30	    const ctx = audioCtx;
31	    const now = ctx.currentTime;
32	    const gain = ctx.createGain();
33	    gain.gain.setValueAtTime(0.0001, now);
34	    gain.gain.exponentialRampToValueAtTime(0.18, now + 0.015);
35	    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.45);
36	    gain.connect(ctx.destination);
37	    const notes = [880, 1175];
38	    notes.forEach((freq, i) => {
39	      const osc = ctx.createOscillator();
40	      osc.type = "sine";
41	      osc.frequency.setValueAtTime(freq, now + i * 0.08);
42	      osc.connect(gain);
43	      osc.start(now + i * 0.08);
44	      osc.stop(now + i * 0.08 + 0.25);
45	    });
46	  } catch { /* ignore */ }
47	}
