function FacilitySidebar({ open, onClose, facilityId, facilityName }: FacilitySidebarProps) {
  const [location, navigate] = useLocation();
  const items = buildFacilityNavItems(facilityId);

  const { data: facilities } = useQuery<FacilityWithCourts[]>({
    queryKey: ["owner-facilities"],
    queryFn: () => customFetch<FacilityWithCourts[]>(`${API_URL}/facilities`),
    enabled: !!facilityId,
    staleTime: 60_000,
  });

  // Unread facility-message count. We deliberately count only message-type
  // notifications routed at /owner/ (set by routes/messages.ts when a player
  // contacts a court owner) — personal DMs land at /messages and are
  // intentionally excluded from this badge.
  const { data: facilityUnread = 0 } = useQuery<number>({
    queryKey: ["owner-facility-msg-unread"],
    queryFn: async () => {
      const notifs = await customFetch<Array<{
        type: string;
        read: boolean;
        link: string | null;
      }>>(`${API_URL}/notifications?limit=200`);
      return notifs.filter(n =>
        n.type === "message" &&
        !n.read &&
        (n.link?.startsWith("/owner/") ?? false),
      ).length;
    },
    staleTime: 30_000,
    refetchInterval: 60_000,
  });

  for (const item of items) {
    if (item.label === "Žinutės") item.badge = facilityUnread;
  }

