1	import { Server as SocketIOServer } from "socket.io";
2	import type { Server as HttpServer } from "node:http";
3	import { clerkClient } from "@clerk/express";
4	import { logger } from "./logger";
5	
6	let io: SocketIOServer | null = null;
7	
8	const presenceMap = new Map<string, { lastSeen: Date; online: boolean }>();
9	
10	export function getPresence(userIds: string[]): Record<string, { online: boolean; lastSeen: string }> {
11	  const result: Record<string, { online: boolean; lastSeen: string }> = {};
12	  for (const uid of userIds) {
13	    const p = presenceMap.get(uid);
14	    result[uid] = p
15	      ? { online: p.online, lastSeen: p.lastSeen.toISOString() }
16	      : { online: false, lastSeen: new Date(0).toISOString() };
17	  }
18	  return result;
19	}
20	
21	export function initSocketIO(httpServer: HttpServer): SocketIOServer {
22	  io = new SocketIOServer(httpServer, {
23	    cors: { origin: true, credentials: true },
24	    transports: ["websocket", "polling"],
25	  });
26	
27	  // Auth middleware — runs before "connection" fires
28	  io.use(async (socket, next) => {
29	    try {
30	      const token = socket.handshake.auth?.token as string | undefined;
31	      const userId = socket.handshake.auth?.userId as string | undefined;
32	
33	      // Agent bypass (dev / automated tests)
34	      const bypassKey = process.env.AGENT_BYPASS_KEY;
35	      if (bypassKey && socket.handshake.auth?.agentKey === bypassKey) {
36	        socket.data.userId = userId ?? "agent-test-user";
37	        return next();
38	      }
39	
40	      // No Clerk secret in dev → trust the userId from the handshake
41	      if (!process.env.CLERK_SECRET_KEY) {
42	        socket.data.userId = userId ?? "anon";
43	        return next();
44	      }
45	
46	      if (!token) return next(new Error("auth:no_token"));
47	
48	      // clerkClient.verifyToken is available on @clerk/express v2+
49	      const payload = await (clerkClient as any).verifyToken(token) as { sub: string };
50	      socket.data.userId = payload.sub;
51	      next();
52	    } catch {
53	      next(new Error("auth:invalid_token"));
54	    }
55	  });
56	
57	  io.on("connection", (socket) => {
58	    const userId: string = socket.data.userId;
59	
60	    // Every authenticated user is always subscribed to their own inbox room
61	    // so that unread_update events reach them regardless of which chat is open.
62	    socket.join(`inbox_${userId}`);
63	    presenceMap.set(userId, { lastSeen: new Date(), online: true });
64	    logger.debug({ userId, id: socket.id }, "socket connected");
65	
66	    // Clients emit this whenever they open a specific conversation.
67	    // The server adds the socket to the appropriate narrow room so future
68	    // new_message events are only delivered to sockets that care about them.
69	    socket.on("join_rooms", (params: {
70	      dmUserId?: string;
71	      courtId?: number;
72	      playerId?: string;
73	      gameId?: number;
74	    }) => {
75	      if (params.dmUserId) {
76	        socket.join(dmRoom(userId, params.dmUserId));
77	      }
78	      if (params.courtId != null && params.playerId) {
79	        socket.join(`facility_${params.courtId}_${params.playerId}`);
80	      }
81	      if (params.gameId != null) {
82	        socket.join(`game_${params.gameId}`);
83	      }
84	    });
85	
86	    socket.on("leave_rooms", (params: {
87	      dmUserId?: string;
88	      courtId?: number;
89	      playerId?: string;
90	      gameId?: number;
91	    }) => {
92	      if (params.dmUserId) {
93	        socket.leave(dmRoom(userId, params.dmUserId));
94	      }
95	      if (params.courtId != null && params.playerId) {
96	        socket.leave(`facility_${params.courtId}_${params.playerId}`);
97	      }
98	      if (params.gameId != null) {
99	        socket.leave(`game_${params.gameId}`);
100	      }
101	    });
102	
103	    socket.on("disconnect", () => {
104	      // Only mark offline if this was the user's last socket
105	      const remaining = io?.sockets.sockets;
106	      const stillOnline = remaining
107	        ? [...remaining.values()].some(s => s !== socket && s.data.userId === userId)
108	        : false;
109	      if (!stillOnline) presenceMap.set(userId, { lastSeen: new Date(), online: false });
110	      logger.debug({ userId, id: socket.id }, "socket disconnected");
111	    });
112	  });
113	
114	  return io;
115	}
116	
117	/** Emit to a room — safe to call even before initSocketIO (silently no-ops). */
118	export function socketEmit(room: string, event: string, data: unknown): void {
119	  try { io?.to(room).emit(event, data); } catch { /* ignore */ }
120	}
121	
122	/** Canonical DM room name — sorts user IDs so both sides produce the same string. */
123	export function dmRoom(uid1: string, uid2: string): string {
124	  return `dm_${[uid1, uid2].sort().join("_")}`;
125	}
