552	// POST /coaches/apply-to-facility — coach applies to teach at every court in a facility
553	router.post("/coaches/apply-to-facility", requireCoach, async (req, res): Promise<void> => {
554	  const userId = getCurrentUserId(req)!;
555	  const { facilityId, message } = req.body ?? {};
556	  const fid = Number(facilityId);
557	  if (!Number.isFinite(fid)) { res.status(400).json({ error: "facilityId is required" }); return; }
558	
559	  const [facility] = await db.select().from(facilitiesTable).where(eq(facilitiesTable.id, fid));
560	  if (!facility) { res.status(404).json({ error: "Facility not found" }); return; }
561	
562	  const [coach] = await db.select().from(coachesTable).where(eq(coachesTable.userId, userId));
563	  if (!coach) { res.status(400).json({ error: "Create your coach profile first" }); return; }
564	
565	  const facilityCourts = await db.select().from(courtsTable).where(eq(courtsTable.facilityId, fid));
566	  if (facilityCourts.length === 0) { res.status(400).json({ error: "Facility has no courts" }); return; }
567	
568	  const courtIds = facilityCourts.map(c => c.id);
569	
570	  // Skip courts where this coach is already approved
571	  const alreadyLinked = await db.select({ courtId: courtCoachesTable.courtId })
572	    .from(courtCoachesTable)
573	    .where(and(eq(courtCoachesTable.coachId, coach.id), inArray(courtCoachesTable.courtId, courtIds)));
574	  const linkedCourtIds = new Set(alreadyLinked.map(r => r.courtId));
575	
576	  // Skip courts with an existing pending invitation by this coach
577	  const existingPending = await db.select({ courtId: courtCoachInvitationsTable.courtId })
578	    .from(courtCoachInvitationsTable)
579	    .where(and(
580	      eq(courtCoachInvitationsTable.targetUserId, userId),
581	      eq(courtCoachInvitationsTable.initiatedBy, "coach"),
582	      eq(courtCoachInvitationsTable.status, "pending"),
583	      inArray(courtCoachInvitationsTable.courtId, courtIds),
584	    ));
585	  const pendingCourtIds = new Set(existingPending.map(r => r.courtId));
586	
587	  const toInsert = facilityCourts
588	    .filter(c => !linkedCourtIds.has(c.id) && !pendingCourtIds.has(c.id))
589	    .map(c => ({
590	      courtId: c.id,
591	      targetUserId: userId,
592	      targetEmail: coach.email,
593	      targetName: coach.name,
594	      initiatedBy: "coach" as const,
595	      status: "pending" as const,
596	      message: message ?? null,
597	    }));
598	
599	  if (toInsert.length === 0) {
600	    res.status(409).json({ error: "Already applied or active at every court in this facility", created: 0 });
601	    return;
602	  }
603	
604	  const created = await db.insert(courtCoachInvitationsTable).values(toInsert).returning();
605	
606	  if (facility.ownerUserId) {
607	    await sendNotification(facility.ownerUserId, "coach_application",
608	      "Naujas trenerio prašymas",
609	      `${coach.name} prašo dirbti „${facility.name}"`,
610	      `/owner/coaches`,
611	    ).catch(() => {});
612	  }
613	
614	  res.status(201).json({
615	    created: created.length,
616	    skipped: facilityCourts.length - created.length,
617	    invitations: created.map(i => ({ ...i, createdAt: i.createdAt.toISOString() })),
618	  });
619	});
