659	    .innerJoin(courtsTable, eq(courtCoachesTable.courtId, courtsTable.id))
660	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
661	    .where(eq(courtCoachesTable.coachId, coach.id));
