300	function ClerkAuthTokenBridge() {
301	  const { getToken } = useAuth();
302	
303	  useEffect(() => {
304	    setAuthTokenGetter(() => getToken());
305	    return () => setAuthTokenGetter(null);
306	  }, [getToken]);
307	
308	  return null;
309	}
