311	function ClerkQueryClientCacheInvalidator() {
312	  const { addListener } = useClerk();
313	  const qc = useQueryClient();
314	  const prevUserIdRef = useRef<string | null | undefined>(undefined);
315	
316	  useEffect(() => {
317	    const unsubscribe = addListener(({ user }) => {
318	      const userId = user?.id ?? null;
319	      if (
320	        prevUserIdRef.current !== undefined &&
321	        prevUserIdRef.current !== userId
322	      ) {
323	        qc.clear();
324	      }
325	      prevUserIdRef.current = userId;
326	    });
327	    return unsubscribe;
328	  }, [addListener, qc]);
329	
330	  return null;
331	}
