333	function ClerkProviderWithRoutes() {
334	  const [, setLocation] = useLocation();
335	  const { locale } = useI18n();
336	  const clerkLocalization = locale === "lt" ? ltLT : locale === "ru" ? ruRU : enUS;
337	
338	  if (!clerkPubKey) {
339	    return (
340	      <QueryClientProvider client={queryClient}>
341	        <FavoritesProvider>
342	          <TooltipProvider>
343	            <Router />
344	            <Toaster />
345	          </TooltipProvider>
346	        </FavoritesProvider>
347	      </QueryClientProvider>
348	    );
349	  }
350	
351	  return (
352	    <ClerkProvider
353	      publishableKey={clerkPubKey}
354	      domain={CLERK_DOMAIN}
355	      isSatellite={false}
356	      localization={clerkLocalization}
357	      signInUrl={`${basePath}/sign-in`}
358	      signUpUrl={`${basePath}/sign-up`}
359	      routerPush={(to) => setLocation(stripBase(to))}
360	      routerReplace={(to) => setLocation(stripBase(to), { replace: true })}
361	    >
362	      <QueryClientProvider client={queryClient}>
363	        <ClerkAuthTokenBridge />
364	        <ClerkQueryClientCacheInvalidator />
365	        <SafeAuthBridge>
366	          <FavoritesProvider>
367	            <TooltipProvider>
368	              <Router />
369	              <Toaster />
370	              <ClerkLoadFailureBanner />
371	            </TooltipProvider>
372	          </FavoritesProvider>
373	        </SafeAuthBridge>
374	      </QueryClientProvider>
375	    </ClerkProvider>
376	  );
377	}
