                <Input
                  id="price"
                  type="text"
                  inputMode="decimal"
                  value={form.pricePerHour}
                  onChange={(e) => setForm((f) => ({ ...f, pricePerHour: e.target.value }))}
                  placeholder="30,00"
                />
                <p className="text-[11px] text-muted-foreground">
                  Įveskite eurais — sistema saugo centais.
                </p>
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="experience">Patirtis (metais)</Label>
                <Input
                  id="experience"
                  type="number"
                  min={0}
                  step={1}
                  value={form.experienceYears}
                  onChange={(e) =>
                    setForm((f) => ({ ...f, experienceYears: e.target.value }))
                  }
                  placeholder="5"
                />
              </div>
            </div>

            <div className="flex items-center justify-between rounded-2xl border bg-card px-4 py-3">
              <div>
                <Label htmlFor="accepting" className="text-sm font-medium">
                  Priimu naujus mokinius
                </Label>
                <p className="text-xs text-muted-foreground mt-0.5">
                  Kai išjungta, jūsų profilis lieka matomas, bet nepriimsite naujų užklausų.
                </p>
              </div>
              <Switch
                id="accepting"
                checked={form.isAcceptingStudents}
                onCheckedChange={(checked) =>
                  setForm((f) => ({ ...f, isAcceptingStudents: checked }))
                }
              />
            </div>

            <div className="flex justify-end pt-2">
              <Button type="submit" disabled={save.isPending}>
                {save.isPending ? "Saugoma..." : "Išsaugoti"}
              </Button>
            </div>
          </form>
        )}
      </div>
    </CoachLayout>
  );
}

import { useQuery } from "@tanstack/react-query";
import { Link } from "wouter";
import { CoachLayout } from "@/components/coach-layout";
import { Skeleton } from "@/components/ui/skeleton";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { MessageSquare } from "lucide-react";
import { customFetch } from "@workspace/api-client-react";

const BASE = import.meta.env.BASE_URL.replace(/\/$/, "");
const API = `${BASE}/api`;

// Mirrors the /dm/threads response shape. We filter client-side for
// contextType === 'coach' so coach-scoped DMs surface here, while personal
// DMs and other contexts stay in the player /messages inbox.
interface Thread {
  otherUserId: string;
  otherUserName: string;
  otherUserImageUrl: string | null;
  lastMessage: {
    body: string;
    createdAt: string;
    senderUserId: string;
    contextType?: string | null;
    contextId?: number | null;
  };
  unread: number;
}

function timeAgo(iso: string) {
  const d = new Date(iso);
  const diff = Date.now() - d.getTime();
  const min = Math.floor(diff / 60_000);
  if (min < 1) return "dabar";
  if (min < 60) return `${min} min.`;
  const h = Math.floor(min / 60);
  if (h < 24) return `${h} val.`;
  return d.toLocaleDateString("lt-LT", { month: "short", day: "numeric" });
}

function initials(name: string) {
  return name.split(" ").map((n) => n[0]).join("").slice(0, 2).toUpperCase();
}

export default function CoachMessages() {
  const { data: threads, isLoading } = useQuery<Thread[]>({
    queryKey: ["coach-inbox"],
    queryFn: () => customFetch<Thread[]>(`${API}/dm/threads`),
    staleTime: 60_000,
  });

  const coachThreads = (threads ?? []).filter(
    (t) => t.lastMessage.contextType === "coach",
  );

  return (
    <CoachLayout title="Žinutės">
      <div className="flex-1 min-h-0 flex flex-col max-w-3xl">
        <div className="px-4 md:px-6 py-3 border-b bg-card">
          <h1 className="text-xl font-semibold tracking-tight">Žinutės</h1>
          <p className="text-xs text-muted-foreground mt-0.5">
            Mokinių užklausos dėl trenerystės.
          </p>
        </div>

        {isLoading ? (
          <div className="p-4 space-y-2">
            {Array.from({ length: 5 }).map((_, i) => (
              <Skeleton key={i} className="h-16 rounded-lg" />
            ))}
          </div>
        ) : coachThreads.length === 0 ? (
          <div className="flex-1 flex flex-col items-center justify-center text-center gap-3 p-10 text-muted-foreground">
            <MessageSquare className="h-10 w-10 opacity-30" />
            <h2 className="text-base font-semibold text-foreground">Užklausų dar nėra</h2>
            <p className="text-sm max-w-md">
              Kai mokiniai parašys jums dėl pamokų, pokalbiai atsiras čia.
            </p>
          </div>
        ) : (
          <ul className="divide-y">
            {coachThreads.map((t) => (
              <li key={t.otherUserId}>
                <Link
                  href={`/messages?u=${t.otherUserId}&n=${encodeURIComponent(t.otherUserName)}`}
                  className="w-full text-left p-4 flex gap-3 hover:bg-muted/40 transition-colors items-start"
                >
                  <Avatar className="h-11 w-11 shrink-0">
                    {t.otherUserImageUrl && (
                      <AvatarImage src={t.otherUserImageUrl} alt={t.otherUserName} />
                    )}
                    <AvatarFallback className="bg-primary/15 text-primary font-semibold text-xs">
                      {initials(t.otherUserName)}
                    </AvatarFallback>
                  </Avatar>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center justify-between gap-2">
                      <span className="font-semibold text-sm truncate">{t.otherUserName}</span>
                      <span className="text-[10px] text-muted-foreground shrink-0">
                        {timeAgo(t.lastMessage.createdAt)}
                      </span>
                    </div>
                    <div className="flex items-center justify-between gap-2 mt-0.5">
                      <p
                        className={`text-xs truncate ${
                          t.unread > 0 ? "font-semibold" : "text-muted-foreground"
                        }`}
                      >
                        {t.lastMessage.body}
                      </p>
                      {t.unread > 0 && (
                        <Badge className="h-5 min-w-5 px-1.5 shrink-0 bg-red-500 hover:bg-red-500 text-white">
                          {t.unread}
                        </Badge>
                      )}
                    </div>
                  </div>
                </Link>
              </li>
            ))}
          </ul>
        )}
      </div>
    </CoachLayout>
  );
}

import { CoachLayout } from "@/components/coach-layout";
import { Users } from "lucide-react";

export default function CoachStudents() {
  // Scaffold only — the relationship between coaches and their students is not
  // yet modelled in the DB. When it lands, this page will list active students
  // with quick links to their lesson history.
  return (
    <CoachLayout title="Mokiniai">
      <div className="px-4 md:px-6 py-6 space-y-6 max-w-4xl">
        <header className="flex flex-col gap-1">
          <h1 className="text-2xl font-semibold tracking-tight">Mokiniai</h1>
          <p className="text-sm text-muted-foreground">
            Visi su jumis dirbantys mokiniai matomi vienoje vietoje.
          </p>
        </header>

        <div className="rounded-2xl border bg-card px-6 py-10 flex flex-col items-center text-center gap-3">
