  | "settings";

interface NavItem {
  id: NavItemId;
  icon: ComponentType<{ className?: string }>;
  label: string;
  href: string;
  match: (location: string) => boolean;
  /** When set, NavLink renders a small unread badge next to the label. */
  badge?: number;
}

function buildFacilityNavItems(facilityId?: number): NavItem[] {
  const fq = facilityId ? `?facility=${facilityId}` : "";
  return [
    {
      id: "dashboard",
      icon: LayoutDashboard,
      label: "Suvestinė",
      href: `/owner/dashboard${fq}`,
      match: (l) => l.startsWith("/owner/dashboard"),
    },
    {
      id: "facilities",
      icon: Building2,
      label: "Mano aikštelės",
      href: facilityId ? `/owner/facility/${facilityId}` : `/owner`,
      match: (l) =>
        l === "/owner" ||
        (l.startsWith("/owner/facility") && !l.endsWith("/messages") && !l.includes("/court/")),
    },
    {
      id: "coaches",
      icon: Users,
      label: "Treneriai",
      href: `/owner/coaches${fq}`,
      match: (l) => l.startsWith("/owner/coaches"),
    },
    {
      id: "messages",
      icon: MessageSquare,
      label: "Žinutės",
      href: `/owner/messages`,
      match: (l: string) => l.startsWith("/owner/messages") || /\/owner\/facility\/\d+\/messages/.test(l),
    },
    {
      id: "tournaments",
      icon: Trophy,
      label: "Turnyrai",
      href: `/owner/tournaments${fq}`,
      match: (l) => l.startsWith("/owner/tournaments"),
    },
    {
      id: "payments",
      icon: CreditCard,
      label: "Mokėjimai",
      href: `/owner/payments${fq}`,
      match: (l) => l.startsWith("/owner/payments"),
    },
    {
      id: "notifications",
      icon: Bell,
      label: "Pranešimai",
      href: `/owner/notifications${fq}`,
      match: (l) => l.startsWith("/owner/notifications"),
    },
    {
      id: "settings",
      icon: Settings,
      label: "Nustatymai",
      href: `/owner/settings${fq}`,
      match: (l) => l.startsWith("/owner/settings"),
    },
  ];
}

