1	import { Router, type IRouter } from "express";
2	import { eq, and, desc, inArray, or, isNull } from "drizzle-orm";
3	import { db, coachesTable, courtCoachesTable, courtCoachInvitationsTable, courtsTable, facilitiesTable } from "@workspace/db";
4	import { requireAuth, getCurrentUserId, isOwner, getUserRole, requireCoach, requireOwner } from "../lib/auth";
5	import { sendNotification } from "../lib/notify";
6	import { sendCoachInviteEmail } from "../lib/email";
7	import { z } from "zod";
8	import { EmailString, OptionalEmailString, OptionalPhoneString } from "@workspace/api-zod";
9	
10	const CoachUpsertBody = z.object({
11	  name: z.string().trim().min(2, "Vardas privalomas"),
12	  email: EmailString,
13	  bio: z.string().optional().nullable(),
14	  photoUrl: z.string().optional().nullable(),
15	  videoUrl: z.string().optional().nullable(),
16	  // Integer cents — clients must multiply euros × 100 before submitting.
17	  // Coerce from string so old form fields that produce "2500" still work.
18	  pricePerHour: z.coerce.number().int().nonnegative().optional().nullable(),
19	  sports: z.array(z.string()).optional(),
20	  availabilityDescription: z.string().optional().nullable(),
21	  phone: OptionalPhoneString,
22	  isAcceptingStudents: z.boolean().optional(),
23	  experienceYears: z.coerce.number().int().nonnegative().optional().nullable(),
24	});
25	
26	const CoachInviteBody = z.object({
27	  targetUserId: z.string().optional(),
28	  targetEmail: OptionalEmailString,
29	  targetName: z.string().optional(),
30	}).refine(d => d.targetUserId || d.targetEmail, {
31	  message: "Reikia targetUserId arba targetEmail",
32	});
33	
34	async function getCourtOwnerUserId(facilityId: number): Promise<string | null> {
35	  const [f] = await db.select({ ownerUserId: facilitiesTable.ownerUserId })
36	    .from(facilitiesTable)
37	    .where(eq(facilitiesTable.id, facilityId));
38	  return f?.ownerUserId ?? null;
39	}
40	
41	const CoachApplyBody = z.object({
42	  message: z.string().optional(),
43	  name: z.string().trim().min(2, "Vardas privalomas").optional(),
44	  email: OptionalEmailString,
45	});
46	
47	const router: IRouter = Router();
48	
49	function formatCoach(c: typeof coachesTable.$inferSelect) {
50	  return {
51	    ...c,
52	    // pricePerHour is integer cents — clients divide by 100 for display.
53	    bio: c.bio ?? undefined,
54	    photoUrl: c.photoUrl ?? undefined,
55	    videoUrl: c.videoUrl ?? undefined,
56	    availabilityDescription: c.availabilityDescription ?? undefined,
57	    phone: c.phone ?? undefined,
58	    experienceYears: c.experienceYears ?? undefined,
59	    createdAt: c.createdAt.toISOString(),
60	  };
61	}
62	
63	function formatPublicCoach(c: typeof coachesTable.$inferSelect) {
64	  return {
65	    id: c.id,
66	    userId: c.userId,
67	    name: c.name,
68	    bio: c.bio ?? undefined,
69	    photoUrl: c.photoUrl ?? undefined,
70	    videoUrl: c.videoUrl ?? undefined,
71	    pricePerHour: c.pricePerHour ?? undefined,
72	    sports: c.sports,
73	    availabilityDescription: c.availabilityDescription ?? undefined,
74	    isAcceptingStudents: c.isAcceptingStudents,
75	    experienceYears: c.experienceYears ?? undefined,
76	    createdAt: c.createdAt.toISOString(),
77	  };
78	}
79	
80	// GET /coaches — list approved coaches, or filter by courtId. Each coach is
81	// enriched with `cities: string[]` from the courts/facilities they teach at.
82	router.get("/coaches", async (req, res): Promise<void> => {
83	  const courtId = req.query.courtId ? parseInt(req.query.courtId as string, 10) : null;
84	
85	  let coaches: Array<typeof coachesTable.$inferSelect>;
86	  if (courtId !== null && !isNaN(courtId)) {
87	    const rows = await db
88	      .select({ coach: coachesTable })
89	      .from(courtCoachesTable)
90	      .innerJoin(coachesTable, eq(courtCoachesTable.coachId, coachesTable.id))
91	      .where(and(eq(courtCoachesTable.courtId, courtId), eq(coachesTable.status, "approved")));
92	    coaches = rows.map(r => r.coach);
93	  } else {
94	    coaches = await db
95	      .select()
96	      .from(coachesTable)
97	      .where(eq(coachesTable.status, "approved"))
98	      .orderBy(coachesTable.createdAt);
99	  }
100	
101	  if (coaches.length === 0) { res.json([]); return; }
102	
103	  const cityRows = await db
104	    .select({
105	      coachId: courtCoachesTable.coachId,
106	      facilityCity: facilitiesTable.city,
107	    })
108	    .from(courtCoachesTable)
109	    .innerJoin(courtsTable, eq(courtCoachesTable.courtId, courtsTable.id))
110	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
111	    .where(inArray(courtCoachesTable.coachId, coaches.map(c => c.id)));
112	
113	  const citiesByCoach = new Map<number, Set<string>>();
114	  for (const row of cityRows) {
115	    const c = row.facilityCity;
116	    if (!c) continue;
117	    if (!citiesByCoach.has(row.coachId)) citiesByCoach.set(row.coachId, new Set());
118	    citiesByCoach.get(row.coachId)!.add(c);
119	  }
120	
121	  res.json(coaches.map(c => ({
122	    ...formatPublicCoach(c),
123	    cities: Array.from(citiesByCoach.get(c.id) ?? []),
124	  })));
125	});
126	
127	// GET /coaches/me — get own coach profile
128	router.get("/coaches/me", requireAuth, async (req, res): Promise<void> => {
129	  const userId = getCurrentUserId(req)!;
130	  const [coach] = await db.select().from(coachesTable).where(eq(coachesTable.userId, userId));
131	  if (!coach) {
132	    res.status(404).json({ error: "No coach profile found" });
133	    return;
134	  }
135	  res.json(formatCoach(coach));
136	});
137	
138	// GET /coaches/:id — get approved coach by id
139	router.get("/coaches/:id", async (req, res): Promise<void> => {
140	  const id = parseInt(String(req.params.id), 10);
141	  if (isNaN(id)) { res.status(400).json({ error: "Invalid id" }); return; }
142	  const [coach] = await db
143	    .select()
144	    .from(coachesTable)
145	    .where(and(eq(coachesTable.id, id), eq(coachesTable.status, "approved")));
146	  if (!coach) { res.status(404).json({ error: "Coach not found" }); return; }
147	  res.json(formatPublicCoach(coach));
148	});
149	
150	// GET /coaches/:id/facilities — public list of facilities/courts a coach is approved at.
151	// Only publicly-visible courts (status approved/active) and verified facilities are returned.
152	router.get("/coaches/:id/facilities", async (req, res): Promise<void> => {
153	  const id = parseInt(String(req.params.id), 10);
154	  if (isNaN(id)) { res.status(400).json({ error: "Invalid id" }); return; }
155	  const [coach] = await db.select().from(coachesTable)
156	    .where(and(eq(coachesTable.id, id), eq(coachesTable.status, "approved")));
157	  if (!coach) { res.json([]); return; }
158	
159	  const rows = await db
160	    .select({ court: courtsTable, facility: facilitiesTable })
161	    .from(courtCoachesTable)
162	    .innerJoin(courtsTable, eq(courtCoachesTable.courtId, courtsTable.id))
163	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
164	    .where(and(
165	      eq(courtCoachesTable.coachId, id),
166	      inArray(courtsTable.status, ["approved", "active"]),
167	      // If court is in a facility, that facility must be verified.
168	      // Standalone courts (no facility) pass this check via the OR.
169	      or(
170	        isNull(courtsTable.facilityId),
171	        eq(facilitiesTable.verificationStatus, "active"),
172	      )!,
173	    ));
174	
175	  type Group = {
176	    facilityId: number | null;
177	    facilityName: string | null;
178	    city: string | null;
179	    address: string | null;
180	    courts: Array<{ id: number; name: string }>;
181	  };
182	  const groups = new Map<string, Group>();
183	  for (const r of rows) {
184	    const key = r.facility?.id != null ? `f${r.facility.id}` : `c${r.court.id}`;
185	    if (!groups.has(key)) {
186	      groups.set(key, {
187	        facilityId: r.facility?.id ?? null,
188	        facilityName: r.facility?.name ?? r.court.name,
189	        city: r.facility?.city ?? null,
190	        address: r.facility?.address ?? null,
191	        courts: [],
192	      });
193	    }
194	    groups.get(key)!.courts.push({ id: r.court.id, name: r.court.name });
195	  }
196	  res.json(Array.from(groups.values()));
197	});
198	
199	// POST /coaches — create coach profile (coach role required, one per user)
200	router.post("/coaches", requireAuth, async (req, res): Promise<void> => {
201	  const userId = getCurrentUserId(req)!;
202	
203	  const callerRole = await getUserRole(userId);
204	  if (callerRole !== "coach" && callerRole !== "admin") {
205	    res.status(403).json({ error: "Forbidden – coach role required" });
206	    return;
207	  }
208	
209	  const parsed = CoachUpsertBody.safeParse(req.body);
210	  if (!parsed.success) {
211	    res.status(400).json({ error: "Invalid body", details: parsed.error.flatten() });
212	    return;
213	  }
214	  const {
215	    name, email, bio, photoUrl, videoUrl, pricePerHour, sports,
216	    availabilityDescription, phone, isAcceptingStudents, experienceYears,
217	  } = parsed.data;
218	
219	  const [existing] = await db.select().from(coachesTable).where(eq(coachesTable.userId, userId));
220	  if (existing) {
221	    res.status(409).json({ error: "Coach profile already exists for this user. Use PUT to update." });
222	    return;
223	  }
224	
225	  const [coach] = await db.insert(coachesTable).values({
226	    userId,
227	    name,
228	    email,
229	    bio: bio ?? null,
230	    photoUrl: photoUrl ?? null,
231	    videoUrl: videoUrl ?? null,
232	    pricePerHour: pricePerHour ?? null,
233	    sports: sports ?? [],
234	    availabilityDescription: availabilityDescription ?? null,
235	    phone: phone ?? null,
236	    ...(isAcceptingStudents !== undefined && { isAcceptingStudents }),
237	    experienceYears: experienceYears ?? null,
238	  }).returning();
239	
240	  res.status(201).json(formatCoach(coach));
241	});
242	
243	// PUT /coaches/:id — update coach profile (own profile or admin)
244	router.put("/coaches/:id", requireAuth, async (req, res): Promise<void> => {
245	  const id = parseInt(String(req.params.id), 10);
246	  if (isNaN(id)) { res.status(400).json({ error: "Invalid id" }); return; }
247	
248	  const userId = getCurrentUserId(req)!;
249	  const [coach] = await db.select().from(coachesTable).where(eq(coachesTable.id, id));
250	  if (!coach) { res.status(404).json({ error: "Coach not found" }); return; }
251	
252	  const canEdit = await isOwner(req, coach.userId);
253	  if (!canEdit && coach.userId !== userId) {
254	    res.status(403).json({ error: "Forbidden" });
255	    return;
256	  }
257	
258	  const parsed = CoachUpsertBody.partial().safeParse(req.body);
259	  if (!parsed.success) {
260	    res.status(400).json({ error: "Invalid body", details: parsed.error.flatten() });
261	    return;
262	  }
263	  const {
264	    name, email, bio, photoUrl, videoUrl, pricePerHour, sports,
265	    availabilityDescription, phone, isAcceptingStudents, experienceYears,
266	  } = parsed.data;
267	
268	  const [updated] = await db.update(coachesTable).set({
269	    ...(name !== undefined && { name }),
270	    ...(email !== undefined && { email }),
271	    bio: bio ?? null,
272	    photoUrl: photoUrl ?? null,
273	    videoUrl: videoUrl ?? null,
274	    pricePerHour: pricePerHour ?? null,
275	    ...(sports !== undefined && { sports }),
276	    availabilityDescription: availabilityDescription ?? null,
277	    phone: phone ?? null,
278	    ...(isAcceptingStudents !== undefined && { isAcceptingStudents }),
279	    experienceYears: experienceYears ?? null,
280	  }).where(eq(coachesTable.id, id)).returning();
281	
282	  res.json(formatCoach(updated));
283	});
284	
285	// PUT /coaches/me — update own coach profile (coach role required)
286	router.put("/coaches/me", requireAuth, async (req, res): Promise<void> => {
287	  const userId = getCurrentUserId(req)!;
288	
289	  const callerRole = await getUserRole(userId);
290	  if (callerRole !== "coach" && callerRole !== "admin") {
291	    res.status(403).json({ error: "Forbidden – coach role required" });
292	    return;
293	  }
294	
295	  const parsed = CoachUpsertBody.safeParse(req.body);
296	  if (!parsed.success) {
297	    res.status(400).json({ error: "Invalid body", details: parsed.error.flatten() });
298	    return;
