285	                              onClick={() => {
286	                                if (confirm(`Pašalinti ${r.coach.name} iš ${r.courtName}?`)) {
287	                                  removeMut.mutate({ courtId: r.courtId, coachId: r.coach.id });
288	                                }
289	                              }}
290	                              disabled={removeMut.isPending}
