  vilniusToUtc("2025-01-15", "12:00").toISOString(),
  "2025-01-15T10:00:00.000Z",
  "winter noon (EET, UTC+2) → 10:00 UTC",
);

eq(
  vilniusToUtc("2025-07-15", "12:00").toISOString(),
  "2025-07-15T09:00:00.000Z",
  "summer noon (EEST, UTC+3) → 09:00 UTC",
);

eq(
  vilniusToUtc("2025-03-30", "02:30").toISOString(),
  "2025-03-30T00:30:00.000Z",
  "spring-forward day 02:30 (before jump, EET) → 00:30 UTC",
);

eq(
  vilniusToUtc("2025-03-30", "04:30").toISOString(),
  "2025-03-30T01:30:00.000Z",
  "spring-forward day 04:30 (after jump, EEST) → 01:30 UTC",
);

eq(
  vilniusToUtc("2025-10-26", "10:00").toISOString(),
  "2025-10-26T08:00:00.000Z",
  "fall-back day 10:00 (EET, post-shift) → 08:00 UTC",
);

eq(
