/**
 * Build a UTC instant representing `YYYY-MM-DD HH:MM` Europe/Vilnius local
 * time. DST-safe: we offset by the timezone's current offset, then correct
 * once if the result lands on a different wall-clock (which happens during
 * spring-forward / fall-back).
 */
export function vilniusToUtc(date: string, hhmm: string): Date {
  const [y, m, d] = date.split("-").map(Number);
  const [hh, mm] = hhmm.split(":").map(Number);
  // First guess: pretend Vilnius is UTC. We'll fix the offset next.
  const naive = new Date(Date.UTC(y, m - 1, d, hh, mm));
  const naiveAsVilnius = partsAtVilnius(naive);
  // Offset minutes between what the naive UTC instant reads as in Vilnius
  // and the target wall clock. Add this to move the instant earlier (Vilnius
  // is east of UTC, so wall-clock 12:00 Vilnius is 09:00 or 10:00 UTC).
  const wantMinutes = hh * 60 + mm;
  const gotMinutes = naiveAsVilnius.hour * 60 + naiveAsVilnius.minute;
  // Account for the case where the formatter reports a different calendar
  // day (e.g. wall-clock 00:30 Vilnius == 21:30 UTC the previous day).
  const wantDay = y * 10000 + m * 100 + d;
  const gotDay = naiveAsVilnius.year * 10000 + naiveAsVilnius.month * 100 + naiveAsVilnius.day;
  let dayDeltaMinutes = 0;
  if (gotDay > wantDay) dayDeltaMinutes = 24 * 60;
  else if (gotDay < wantDay) dayDeltaMinutes = -24 * 60;
  const offsetMinutes = gotMinutes + dayDeltaMinutes - wantMinutes;
  return new Date(naive.getTime() - offsetMinutes * 60_000);
}

