37	export async function handleStripeWebhook(req: Request, res: Response): Promise<void> {
38	  const sigHeader = req.headers["stripe-signature"];
39	  if (!sigHeader) {
40	    res.status(400).json({ error: "Missing stripe-signature header" });
41	    return;
42	  }
43	  const signature = Array.isArray(sigHeader) ? sigHeader[0] : sigHeader;
44	
45	  let stripe: Stripe;
46	  let webhookSecret: string;
47	  try {
48	    stripe = getStripe();
49	    webhookSecret = getStripeWebhookSecret();
50	  } catch (err: any) {
51	    logger.error({ err }, "Stripe not configured for webhook");
52	    res.status(503).json({ error: "Stripe not configured" });
53	    return;
54	  }
55	
56	  if (!Buffer.isBuffer(req.body)) {
57	    logger.error(
58	      "Stripe webhook body is not a Buffer — express.json() must run AFTER this route",
59	    );
60	    res.status(400).json({ error: "Invalid body" });
61	    return;
62	  }
63	
64	  let event: Stripe.Event;
65	  try {
66	    event = stripe.webhooks.constructEvent(req.body, signature, webhookSecret);
67	  } catch (err: any) {
68	    logger.warn({ err: err?.message }, "Stripe webhook signature verification failed");
69	    res.status(400).json({ error: `Webhook Error: ${err?.message}` });
70	    return;
71	  }
72	
73	  try {
74	    switch (event.type) {
75	      case "checkout.session.completed":
76	      case "checkout.session.async_payment_succeeded": {
77	        const session = event.data.object as Stripe.Checkout.Session;
78	        await handleCheckoutCompleted(session);
79	        break;
80	      }
81	      case "checkout.session.expired": {
82	        const session = event.data.object as Stripe.Checkout.Session;
83	        await handleCheckoutExpired(session);
84	        break;
85	      }
86	      case "account.updated": {
87	        const account = event.data.object as Stripe.Account;
88	        await handleAccountUpdated(account);
89	        break;
90	      }
91	      default:
92	        logger.debug({ type: event.type }, "Stripe webhook received (unhandled)");
93	    }
94	  } catch (err) {
95	    logger.error({ err, type: event.type }, "Stripe webhook handler failed");
96	    // Still return 200 so Stripe doesn't retry indefinitely on our app errors;
97	    // bookings are already protected by /api/payments/confirm fallback.
98	  }
99	
100	  res.status(200).json({ received: true });
101	}
102	
103	// ─── Handlers ────────────────────────────────────────────────────────────────
104	
105	async function handleCheckoutCompleted(session: Stripe.Checkout.Session): Promise<void> {
106	  if (session.payment_status !== "paid") return;
107	
108	  // ── 1. Try to find a booking by stripeSessionId (covers regular and split-host payments) ──
109	  const rows = await db
110	    .select({
111	      booking: bookingsTable,
112	      courtName: courtsTable.name,
113	      courtId: courtsTable.id,
114	      courtAddress: facilitiesTable.address,
115	      courtCity: facilitiesTable.city,
116	      courtPhone: courtsTable.phone,
117	      courtImageUrl: courtsTable.imageUrl,
118	      ownerName: facilitiesTable.companyName,
119	      ownerEmail: facilitiesTable.email,
120	      instantBookingEnabled: courtsTable.instantBookingEnabled,
121	      hasSmartLock: courtsTable.hasSmartLock,
122	    })
123	    .from(bookingsTable)
124	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
125	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
126	    .where(eq(bookingsTable.stripeSessionId, session.id));
127	
128	  if (rows[0]) {
129	    const booking = rows[0].booking;
130	
131	    if (booking.isSplit) {
132	      // ── Split booking: this is the HOST's first payment ──────────────────
133	      // CAS: pending → awaiting_players (reserves the court slot)
134	      const updatedRows = await db
135	        .update(bookingsTable)
136	        .set({ status: "awaiting_players" })
137	        .where(and(
138	          eq(bookingsTable.stripeSessionId, session.id),
139	          eq(bookingsTable.status, "pending"),
140	        ))
141	        .returning();
142	
143	      if (updatedRows.length === 0) {
144	        // Already processed (awaiting_players or confirmed). Still mark participant paid.
145	      }
146	
147	      // Mark host participant as paid
