1	import { and, eq, gte, lt } from "drizzle-orm";
2	import {
3	  db,
4	  coachAvailabilitiesTable,
5	  coachBlockedSlotsTable,
6	} from "@workspace/db";
7	
8	const COACH_TZ = "Europe/Vilnius";
9	const SLOT_MINUTES = 30;
10	
11	/**
12	 * A single availability slot returned to clients. `start` and `end` are full
13	 * ISO timestamps (UTC) so callers can render them in any timezone. `label`
14	 * is the HH:MM Europe/Vilnius local time the slot starts — what coaches and
15	 * students actually think of as "the 14:00 slot".
16	 */
17	export interface CoachAvailabilitySlot {
18	  start: string;
19	  end: string;
20	  label: string;
21	}
22	
23	// ─── Timezone helpers ────────────────────────────────────────────────────────
24	//
25	// We deliberately avoid pulling in luxon / date-fns-tz for one function. The
26	// trick: format a UTC instant into the target zone and parse the parts back
27	// out — that gives us "what time is it in Vilnius right now". Building a
28	// UTC timestamp from a Vilnius wall-clock time is the reverse: pick a UTC
29	// candidate, format it back into Vilnius, compare wall clocks, and adjust.
30	
31	const TZ_FORMATTER = new Intl.DateTimeFormat("en-GB", {
32	  timeZone: COACH_TZ,
33	  year: "numeric", month: "2-digit", day: "2-digit",
34	  hour: "2-digit", minute: "2-digit", second: "2-digit",
35	  hour12: false,
36	});
37	
38	interface WallClock {
39	  year: number;
40	  month: number;
41	  day: number;
42	  hour: number;
43	  minute: number;
44	  dayOfWeek: number;
45	}
46	
47	function partsAtVilnius(d: Date): WallClock {
48	  const parts = TZ_FORMATTER.formatToParts(d);
49	  const map: Record<string, string> = {};
50	  for (const p of parts) map[p.type] = p.value;
51	  const year = Number(map.year);
52	  const month = Number(map.month);
53	  const day = Number(map.day);
54	  const hour = map.hour === "24" ? 0 : Number(map.hour);
55	  const minute = Number(map.minute);
56	  // JavaScript's getUTCDay() returns 0..6 with Sunday=0 — same convention as
57	  // we store in coach_availabilities.day_of_week. We compute it from the
58	  // formatted date so a 23:30 UTC instant maps to "tomorrow" in Vilnius.
59	  const dow = new Date(Date.UTC(year, month - 1, day)).getUTCDay();
60	  return { year, month, day, hour, minute, dayOfWeek: dow };
61	}
62	
63	/**
64	 * Build a UTC instant representing `YYYY-MM-DD HH:MM` Europe/Vilnius local
65	 * time. DST-safe: we iterate twice so that when the first offset correction
66	 * lands on the wrong side of a DST jump (e.g. 02:30 spring-forward day where
67	 * the naive candidate falls in EEST instead of EET) the second pass nudges
68	 * it back. Two iterations are always enough — the worst-case correction is
69	 * exactly one hour.
70	 */
71	export function vilniusToUtc(date: string, hhmm: string): Date {
72	  const [y, m, d] = date.split("-").map(Number);
73	  const [hh, mm] = hhmm.split(":").map(Number);
74	  const wantMinutes = hh * 60 + mm;
75	  const wantDay = y * 10000 + m * 100 + d;
76	  // First guess: pretend Vilnius is UTC. The loop corrects offsets and DST.
77	  let candidate = new Date(Date.UTC(y, m - 1, d, hh, mm));
78	  for (let iter = 0; iter < 2; iter++) {
79	    const got = partsAtVilnius(candidate);
80	    const gotMinutes = got.hour * 60 + got.minute;
81	    const gotDay = got.year * 10000 + got.month * 100 + got.day;
82	    let dayDeltaMinutes = 0;
83	    if (gotDay > wantDay) dayDeltaMinutes = 24 * 60;
84	    else if (gotDay < wantDay) dayDeltaMinutes = -24 * 60;
85	    const offsetMinutes = gotMinutes + dayDeltaMinutes - wantMinutes;
86	    if (offsetMinutes === 0) break;
87	    candidate = new Date(candidate.getTime() - offsetMinutes * 60_000);
88	  }
89	  return candidate;
90	}
91	
92	export function hhmmInVilnius(d: Date): string {
93	  const p = partsAtVilnius(d);
94	  return `${String(p.hour).padStart(2, "0")}:${String(p.minute).padStart(2, "0")}`;
95	}
96	
97	// ─── Slot math ───────────────────────────────────────────────────────────────
98	
99	export interface Range {
100	  start: number; // ms epoch
101	  end: number;
102	}
103	
104	/**
105	 * Subtract a set of blocking ranges from a single open range. Returns 0..n
106	 * sub-ranges that survived. Inputs need not be sorted; we sort the blockers
107	 * once and sweep linearly.
108	 */
109	export function subtractRanges(open: Range, blockers: Range[]): Range[] {
110	  const active = blockers
111	    .filter((b) => b.end > open.start && b.start < open.end)
112	    .map((b) => ({ start: Math.max(b.start, open.start), end: Math.min(b.end, open.end) }))
113	    .sort((a, b) => a.start - b.start);
114	
115	  const out: Range[] = [];
116	  let cursor = open.start;
117	  for (const b of active) {
118	    if (b.start > cursor) out.push({ start: cursor, end: b.start });
119	    cursor = Math.max(cursor, b.end);
120	  }
121	  if (cursor < open.end) out.push({ start: cursor, end: open.end });
122	  return out;
123	}
124	
125	/**
126	 * Slice a continuous range into back-to-back 30-min slots, dropping any
127	 * trailing remainder that's shorter than a full slot.
128	 */
129	export function explodeIntoSlots(r: Range): CoachAvailabilitySlot[] {
130	  const step = SLOT_MINUTES * 60_000;
131	  const slots: CoachAvailabilitySlot[] = [];
132	  for (let t = r.start; t + step <= r.end; t += step) {
133	    const startD = new Date(t);
134	    const endD = new Date(t + step);
135	    slots.push({
136	      start: startD.toISOString(),
137	      end: endD.toISOString(),
138	      label: hhmmInVilnius(startD),
139	    });
140	  }
141	  return slots;
142	}
143	
144	// ─── Public API ──────────────────────────────────────────────────────────────
145	
146	/**
147	 * Returns the 30-minute slots a coach is available on the given `date`
148	 * (YYYY-MM-DD, interpreted in Europe/Vilnius). The set is computed from
149	 *   • coach_availabilities for this weekday, minus
150	 *   • coach_blocked_slots overlapping the date.
151	 *
152	 * Coach bookings will be subtracted by a follow-up strike once
153	 * bookings.coachId starts getting populated by the coach-booking flow.
154	 */
155	export async function getCoachAvailability(
156	  coachId: number,
157	  date: string,
158	): Promise<CoachAvailabilitySlot[]> {
159	  // Anchor the day window: 00:00 Vilnius local through 00:00 next-day Vilnius
160	  // local. Both ends are real UTC instants — the day is 23, 24, or 25 hours
161	  // long depending on DST, and that's fine because we compute the wall-clock
162	  // bounds from coach_availabilities below.
163	  const dayStartUtc = vilniusToUtc(date, "00:00");
164	  const dow = partsAtVilnius(dayStartUtc).dayOfWeek;
165	
166	  const [hours, blocks] = await Promise.all([
167	    db.select()
168	      .from(coachAvailabilitiesTable)
169	      .where(and(
170	        eq(coachAvailabilitiesTable.coachId, coachId),
171	        eq(coachAvailabilitiesTable.dayOfWeek, dow),
172	      )),
173	    db.select()
174	      .from(coachBlockedSlotsTable)
175	      .where(and(
176	        eq(coachBlockedSlotsTable.coachId, coachId),
177	        // Window the blocker query so we don't load all-time blocks for one
178	        // day's lookup. We use a generous +1-day upper bound to catch blocks
179	        // that cross midnight.
180	        gte(coachBlockedSlotsTable.endTime, dayStartUtc),
181	        lt(coachBlockedSlotsTable.startTime, new Date(dayStartUtc.getTime() + 36 * 3600 * 1000)),
182	      )),
183	  ]);
184	
185	  if (hours.length === 0) return [];
186	
187	  const blockers: Range[] = blocks.map((b) => ({
188	    start: b.startTime.getTime(),
189	    end: b.endTime.getTime(),
190	  }));
191	
192	  const slots: CoachAvailabilitySlot[] = [];
193	  for (const h of hours) {
194	    const openStart = vilniusToUtc(date, h.startTime).getTime();
195	    const openEnd = vilniusToUtc(date, h.endTime).getTime();
196	    if (openEnd <= openStart) continue;
197	    for (const sub of subtractRanges({ start: openStart, end: openEnd }, blockers)) {
198	      slots.push(...explodeIntoSlots(sub));
199	    }
200	  }
201	
202	  slots.sort((a, b) => a.start.localeCompare(b.start));
203	  return slots;
204	}
