1	import { Router, type IRouter } from "express";
2	import { eq, and, inArray } from "drizzle-orm";
3	import { db } from "@workspace/db";
4	import { userRolesTable, coachesTable, userProfilesTable } from "@workspace/db/schema";
5	import { requireAuth, requireAdmin, ensureUserRole, getCurrentUserId } from "../lib/auth";
6	import { getAuth, clerkClient } from "@clerk/express";
7	import { z } from "zod";
8	import { sendAdminRoleRequestEmail } from "../lib/email";
9	import { sendAdminNotification } from "../lib/notify";
10	
11	const router: IRouter = Router();
12	
13	/** GET /me/role — returns the current user's role + status, auto-creates player if first visit */
14	router.get("/me/role", requireAuth, async (req, res): Promise<void> => {
15	  const { userId } = getAuth(req);
16	  const role = await ensureUserRole(userId!);
17	  const [row] = await db.select().from(userRolesTable).where(eq(userRolesTable.userId, userId!));
18	  res.json({
19	    userId,
20	    role,
21	    status: row?.status ?? "active",
22	    pendingRole: row?.pendingRole ?? null,
23	    rejectionReason: row?.rejectionReason ?? null,
24	  });
25	});
26	
27	/** POST /me/request-role — submit a role upgrade request (coach or owner) */
28	const RequestRoleBody = z.object({
29	  pendingRole: z.enum(["coach", "owner"]),
30	  requestData: z.record(z.unknown()).optional(),
31	});
32	
33	router.post("/me/request-role", requireAuth, async (req, res): Promise<void> => {
34	  const userId = getCurrentUserId(req);
35	  if (!userId) { res.status(401).json({ error: "Unauthorized" }); return; }
36	
37	  const parsed = RequestRoleBody.safeParse(req.body);
38	  if (!parsed.success) { res.status(400).json({ error: "Invalid request body" }); return; }
39	
40	  const { pendingRole, requestData } = parsed.data;
41	
42	  const [existing] = await db.select().from(userRolesTable).where(eq(userRolesTable.userId, userId));
43	  if (existing?.role === pendingRole) {
44	    res.status(400).json({ error: "You already have this role" }); return;
45	  }
46	  if (existing?.status === "pending_approval") {
47	    res.status(400).json({ error: "You already have a pending role request" }); return;
48	  }
49	
50	  const [row] = await db
51	    .insert(userRolesTable)
52	    .values({
53	      userId,
54	      role: existing?.role ?? "player",
55	      status: "pending_approval",
56	      pendingRole,
57	      requestData: requestData ? JSON.stringify(requestData) : null,
58	      rejectionReason: null,
59	    })
60	    .onConflictDoUpdate({
61	      target: userRolesTable.userId,
62	      set: {
63	        status: "pending_approval",
64	        pendingRole,
65	        requestData: requestData ? JSON.stringify(requestData) : null,
66	        rejectionReason: null,
67	        updatedAt: new Date(),
68	      },
69	    })
70	    .returning();
71	
72	  await sendAdminRoleRequestEmail({
73	    userId,
74	    pendingRole,
75	    requestData: requestData ?? {},
76	  }).catch(() => {});
77	
78	  const roleLabel = pendingRole === "coach" ? "trenerio" : "savininko";
79	  await sendAdminNotification(
80	    `Nauja ${roleLabel} rolės užklausa`,
81	    `Vartotojas pateikė prašymą gauti ${roleLabel} teises.`,
82	    "/admin?tab=users",
83	  );
84	
85	  res.json(row);
86	});
87	
88	/** DELETE /me/role-request — cancel the user's pending role request */
89	router.delete("/me/role-request", requireAuth, async (req, res): Promise<void> => {
90	  const userId = getCurrentUserId(req);
91	  if (!userId) { res.status(401).json({ error: "Unauthorized" }); return; }
92	
93	  const [existing] = await db.select().from(userRolesTable).where(eq(userRolesTable.userId, userId));
94	  if (!existing || existing.status !== "pending_approval" || !existing.pendingRole) {
95	    res.status(400).json({ error: "Nėra aktyvaus prašymo, kurį būtų galima atšaukti" });
96	    return;
97	  }
98	
99	  const cancelledRole = existing.pendingRole;
100	
101	  const [row] = await db
102	    .update(userRolesTable)
103	    .set({
104	      status: "active",
105	      pendingRole: null,
106	      requestData: null,
107	      rejectionReason: null,
108	      updatedAt: new Date(),
109	    })
110	    .where(eq(userRolesTable.userId, userId))
111	    .returning();
112	
113	  const roleLabel = cancelledRole === "coach" ? "trenerio" : "savininko";
114	  await sendAdminNotification(
115	    `${roleLabel.charAt(0).toUpperCase() + roleLabel.slice(1)} rolės užklausa atšaukta`,
116	    `Vartotojas atšaukė savo prašymą gauti ${roleLabel} teises.`,
117	    "/admin/roles",
118	  ).catch(() => {});
119	
120	  res.json(row);
121	});
122	
123	/** GET /admin/role-requests — list all pending role requests (admin only) */
124	router.get("/admin/role-requests", requireAdmin, async (_req, res): Promise<void> => {
125	  const rows = await db
126	    .select()
127	    .from(userRolesTable)
128	    .where(eq(userRolesTable.status, "pending_approval"));
129	  res.json(rows);
130	});
131	
132	/** POST /admin/role-requests/:userId/approve — approve a role request */
133	router.post("/admin/role-requests/:userId/approve", requireAdmin, async (req, res): Promise<void> => {
134	  const userId = String(req.params.userId);
135	
