    const matchesSport = activeSports.size === ALL_SPORTS.length || c.sports.some(s => activeSports.has(s));
    const matchesPrice = c.pricePerHour == null || c.pricePerHour <= maxPrice;
    const matchesCity = !searchCity || (c.cities ?? []).some(
