  const flexibleCancel = coach.cancellationPolicy === "flexible";
  const willTravel = coach.travelPolicy === "any_court";

  return (
    <Link href={`/coach/${coach.id}`}>
      <div className="group bg-card border rounded-2xl overflow-hidden shadow-sm hover:shadow-lg hover:-translate-y-0.5 transition-all duration-200 cursor-pointer flex flex-col h-full">
        <div className="relative h-40 bg-muted flex items-center justify-center overflow-hidden">
          {coach.photoUrl ? (
            <img
              src={coach.photoUrl}
              alt={coach.name}
              className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
            />
          ) : (
            <div className="w-20 h-20 rounded-full bg-primary/15 flex items-center justify-center border-2 border-primary/20">
              <span className="text-2xl font-bold text-primary">{initials}</span>
            </div>
          )}
          {coach.pricePerHour != null && (
            <div className="absolute top-2.5 right-2.5 bg-black/60 backdrop-blur rounded-xl px-2.5 py-1 text-white text-xs font-semibold flex items-center gap-1">
              <Euro className="w-3 h-3" />
              {centsToEuroString(coach.pricePerHour)}€/val
            </div>
          )}
          {windowAvailable && (
            <div className="absolute top-2.5 left-2.5 bg-green-500/90 backdrop-blur rounded-full px-2.5 py-1 text-white text-[10px] font-semibold flex items-center gap-1.5">
              <span className="w-1.5 h-1.5 rounded-full bg-white animate-pulse" />
              Laisvas
            </div>
          )}
        </div>

        <div className="p-4 flex flex-col gap-2.5 flex-1">
          <h3 className="font-semibold text-base leading-tight truncate">{coach.name}</h3>

          {coach.sports.length > 0 && (
            <div className="flex flex-wrap gap-1.5">
              {coach.sports.slice(0, 2).map(s => (
                <SportPill key={s} sport={s} variant="subtle" />
              ))}
              {coach.sports.length > 2 && (
                <span className="text-[11px] px-2 py-0.5 rounded-full bg-muted text-muted-foreground font-medium">
                  +{coach.sports.length - 2}
                </span>
              )}
            </div>
          )}

          {audienceSet.size > 0 && (
            <div className="flex flex-wrap gap-1">
              {Array.from(audienceSet).slice(0, 4).map(a => (
                <span
                  key={a}
                  className="text-[10px] font-medium px-2 py-0.5 rounded-full bg-secondary text-secondary-foreground"
                >
                  {AUDIENCE_LT[a] ?? a}
                </span>
              ))}
            </div>
          )}

          {(flexibleCancel || willTravel) && (
            <div className="flex flex-wrap gap-1">
              {flexibleCancel && (
                <span className="text-[10px] font-medium px-2 py-0.5 rounded-full bg-emerald-500/15 text-emerald-700 dark:text-emerald-400">
                  Lankstus atšaukimas
                </span>
              )}
              {willTravel && (
                <span className="text-[10px] font-medium px-2 py-0.5 rounded-full bg-sky-500/15 text-sky-700 dark:text-sky-400">
                  Atvyksta į bet kurią aikštelę
                </span>
              )}
            </div>
          )}

          {coach.bio && (
            <p className="text-xs text-muted-foreground leading-relaxed line-clamp-2">{coach.bio}</p>
          )}
        </div>

        <div className="px-4 pb-4">
          <Button size="sm" variant="outline" className="w-full text-xs group-hover:bg-primary group-hover:text-primary-foreground transition-colors">
            Peržiūrėti profilį
          </Button>
        </div>
      </div>
    </Link>
  );
}

