78	/**
79	 * Build a round avatar-style marker for a coach. Uses the photo as a foreignObject
80	 * when available so Google Maps renders it as an inline SVG marker (no external
81	 * fetch). Falls back to a colored circle with the coach's initials.
82	 */
83	function buildCoachMarkerUrl(opts: {
84	  initials: string;
85	  color: string;
86	  photoSrc: string | null;
87	  isSelected: boolean;
88	  travels: boolean;
89	}): string {
90	  const size = opts.isSelected ? 52 : 42;
91	  const border = opts.isSelected ? 3 : 2.5;
92	  const cx = size / 2;
93	  const cy = size / 2;
94	  const r = size / 2 - border / 2;
95	
96	  // Photo (when available) is rendered as a clipped <image>; otherwise we draw
97	  // the initials. The colored ring + small "Plane" notch (when travels=true)
98	  // sit on top so the marker reads at a glance.
99	  const photoNode = opts.photoSrc
100	    ? `<defs><clipPath id="c"><circle cx="${cx}" cy="${cy}" r="${r - 1}"/></clipPath></defs>
101	       <image href="${opts.photoSrc}" x="${cx - r}" y="${cy - r}" width="${r * 2}" height="${r * 2}" clip-path="url(#c)" preserveAspectRatio="xMidYMid slice"/>`
102	    : `<circle cx="${cx}" cy="${cy}" r="${r - 1}" fill="${opts.color}"/>
103	       <text x="${cx}" y="${cy + 4}" text-anchor="middle" font-family="system-ui,-apple-system,sans-serif" font-weight="700" font-size="${size * 0.4}" fill="white">${opts.initials}</text>`;
104	
105	  const travelBadge = opts.travels
106	    ? `<circle cx="${size - 8}" cy="8" r="7" fill="#0ea5e9" stroke="white" stroke-width="1.5"/>
107	       <path d="M${size - 10.5} 7.5 L${size - 6.5} 7.5 M${size - 8} 5.5 L${size - 8} 10.5" stroke="white" stroke-width="1.4" stroke-linecap="round"/>`
108	    : "";
109	
110	  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 ${size} ${size}">
111	    <circle cx="${cx}" cy="${cy}" r="${r}" fill="${opts.color}" stroke="white" stroke-width="${border}"/>
112	    ${photoNode}
113	    ${travelBadge}
114	  </svg>`;
115	
116	  return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
117	}
