91	async function fetchCoaches(f: CoachQueryFilters): Promise<Coach[]> {
92	  const params = new URLSearchParams();
93	  if (f.date && f.startTime && f.endTime) {
94	    params.set("date", f.date);
95	    params.set("startTime", f.startTime);
96	    params.set("endTime", f.endTime);
97	  }
98	  if (f.audiences?.length) params.set("audiences", f.audiences.join(","));
99	  if (f.travelPolicies?.length) params.set("travelPolicies", f.travelPolicies.join(","));
100	  if (f.cancellationPolicies?.length) params.set("cancellationPolicies", f.cancellationPolicies.join(","));
101	  if (f.city) params.set("city", f.city);
102	  if (f.sport) params.set("sport", f.sport);
103	  const r = await fetch(`${API}/coaches?${params.toString()}`);
104	  if (!r.ok) return [];
105	  return r.json();
106	}
