115	function addMinutes(hhmm: string, mins: number): string {
116	  const [h, m] = hhmm.split(":").map(Number);
117	  const total = h * 60 + m + mins;
118	  const hh = Math.floor(total / 60).toString().padStart(2, "0");
119	  const mm = (total % 60).toString().padStart(2, "0");
120	  return `${hh}:${mm}`;
