import { BackButton } from "@/components/back-button";
import { validateEmail, validatePhone } from "@/lib/validators";
import { centsToEuroString, euroStringToCents } from "@/lib/money";

const BASE = import.meta.env.BASE_URL.replace(/\/$/, "");
const API = `${BASE}/api`;

const SPORT_OPTIONS = ["tennis", "basketball", "padel", "football", "badminton", "squash", "table_tennis", "golf", "snooker", "bowling"];
interface Coach {
  id: number;
  userId: string;
  name: string;
  email: string;
  bio?: string;
  photoUrl?: string;
  videoUrl?: string;
  pricePerHour?: number;
  sports: string[];
  availabilityDescription?: string;
  phone?: string;
}

async function fetchCoach(id: string): Promise<Coach> {
  const r = await fetch(`${API}/coaches/${id}`);
  if (!r.ok) throw new Error("Coach not found");
  return r.json();
}

async function fetchMyCoach(): Promise<Coach | null> {
  const r = await fetch(`${API}/coaches/me`, { credentials: "include" });
  if (r.status === 404) return null;
  if (!r.ok) throw new Error("Failed to fetch coach profile");
  return r.json();
}

interface CoachService {
  id: number;
  coachId: number;
  name: string;
  description: string | null;
  sport: string;
  courtId: number | null;
  durationMin: number;
  priceCents: number;
  maxParticipants: number;
  audienceLevel: string | null;
  isActive: boolean;
  sortOrder: number;
}

const AUDIENCE_LT: Record<string, string> = {
  kids: "Vaikai",
  beginners: "Pradedantieji",
  advanced: "Pažengę",
  pros: "Profesionalai",
};

const AUDIENCE_OPTIONS = [
  { value: "kids", label: "Vaikai" },
  { value: "beginners", label: "Pradedantieji" },
  { value: "advanced", label: "Pažengę" },
  { value: "pros", label: "Profesionalai" },
] as const;

const DURATION_OPTIONS = [
  { value: "30", label: "30 min" },
  { value: "60", label: "1 val." },
  { value: "90", label: "1.5 val." },
  { value: "120", label: "2 val." },
] as const;

// Mirror of the server-side ceiling in routes/coach-services.ts. The button
// is hidden once a coach reaches this many services so we don't dispatch a
// POST we know will be rejected.
const SERVICE_CATALOG_LIMIT = 15;

const COURT_ANY_VALUE = "__any__";
const AUDIENCE_NONE_VALUE = "__none__";

const serviceFormSchema = z.object({
  name: z.string().trim().min(1, "Pavadinimas yra privalomas").max(120, "Per ilgas"),
  description: z.string().trim().max(1000, "Per ilgas aprašymas"),
  sport: z.string().trim().min(1, "Pasirinkite sporto šaką"),
  durationMin: z.string().refine(
    v => ["30", "60", "90", "120"].includes(v),
    { message: "Pasirinkite trukmę" },
  ),
  // Stored as a string for the controlled <Input>. Accepts comma OR dot
  // decimal — converted to integer cents via Math.round at submit time.
  priceEur: z.string()
    .trim()
    .min(1, "Įveskite kainą")
    .regex(/^\d+([.,]\d{1,2})?$/, "Netinkamas formatas, pvz. 35 arba 35,50"),
  maxParticipants: z.string().refine(
    v => /^[1-8]$/.test(v),
    { message: "Nuo 1 iki 8" },
  ),
  // Empty string = no audience filter applied to this service.
  audienceLevel: z.string(),
  // COURT_ANY_VALUE = bookable at any of the coach's affiliated courts (null
  // on the wire). Otherwise the numeric courtId as a string.
  courtBinding: z.string().min(1, "Pasirinkite aikštelę"),
  isActive: z.boolean(),
});

type ServiceFormValues = z.infer<typeof serviceFormSchema>;

function formatDuration(min: number): string {
  if (min < 60) return `${min} min`;
  const hours = min / 60;
  if (Number.isInteger(hours)) return `${hours} val.`;
  // 1.5 → "1,5 val." in Lithuanian locale convention
  return `${hours.toString().replace(".", ",")} val.`;
}

function priceEurToCents(raw: string): number {
  const normalized = raw.replace(",", ".");
  const euros = parseFloat(normalized);
  if (!Number.isFinite(euros) || euros < 0) return 0;
  // Math.round avoids floating-point drift: 35.50 → 3550 cents.
  return Math.round(euros * 100);
}

interface CoachFacilityGroup {
  facilityId: number | null;
  facilityName: string | null;
  city: string | null;
  address: string | null;
  courts: Array<{ id: number; name: string }>;
}

interface CoachApplication {
  invitationId: number;
  courtId: number;
  courtName: string;
  facilityId: number | null;
  facilityName: string | null;
  status: string;
  initiatedBy: string;
  message: string | null;
  createdAt: string;
}

interface FacilityOption {
  id: number;
  name: string;
  city?: string | null;
  address?: string | null;
}

export default function CoachPage() {
  const { id } = useParams<{ id?: string }>();
  const { user, isSignedIn } = useUser();
  const { toast } = useToast();
  const qc = useQueryClient();

  const isOwnProfileRoute = !id || id === "me";

  const { data: coach, isLoading } = useQuery<Coach | null>({
    queryKey: isOwnProfileRoute ? ["coach", "me"] : ["coach", id],
    queryFn: isOwnProfileRoute ? fetchMyCoach : () => fetchCoach(id!),
    enabled: isOwnProfileRoute ? !!isSignedIn : true,
    retry: false,
  });

  const isOwn = isOwnProfileRoute || (coach?.userId && user?.id === coach.userId);
  const coachId = coach?.id;

  // Public facilities the coach is approved at — visible on every profile view
  const facilitiesQ = useQuery<CoachFacilityGroup[]>({
    queryKey: ["coach-facilities", coachId],
    queryFn: () => fetch(`${API}/coaches/${coachId}/facilities`).then(r => r.json()),
    enabled: !!coachId,
  });

  // Coach services (lesson types) — visible on every profile view. Non-owners
  // get only active services from the API; owners get the full list.
  const servicesQ = useQuery<CoachService[]>({
    queryKey: ["coach-services", coachId],
    queryFn: () => fetch(`${API}/coaches/${coachId}/services`, { credentials: "include" }).then(r => r.ok ? r.json() : []),
    enabled: !!coachId,
  });

  // Owner-only data: pending applications + facility picker
  const applicationsQ = useQuery<CoachApplication[]>({
    queryKey: ["coach", "me", "applications"],
    queryFn: () => fetch(`${API}/coaches/me/applications`, { credentials: "include" }).then(r => r.ok ? r.json() : []),
    enabled: !!isOwn && !!coachId,
  });

  const allFacilitiesQ = useQuery<FacilityOption[]>({
    queryKey: ["facilities", "public"],
    queryFn: () => fetch(`${API}/facilities/public`).then(r => r.ok ? r.json() : []),
    enabled: !!isOwn && !!coachId,
  });

  const [applyOpen, setApplyOpen] = useState(false);
  const [applyFacilityId, setApplyFacilityId] = useState<number | null>(null);
  const [applyMessage, setApplyMessage] = useState("");
  const [facilityFilter, setFacilityFilter] = useState("");

  const applyMut = useMutation({
    mutationFn: async () => {
      if (!applyFacilityId) throw new Error("Pasirinkite vietą");
      const r = await fetch(`${API}/coaches/apply-to-facility`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({ facilityId: applyFacilityId, message: applyMessage || undefined }),
      });
      if (!r.ok) {
        const err = await r.json().catch(() => ({}));
        throw new Error(err.error ?? "Nepavyko pateikti paraiškos");
      }
      return r.json();
    },
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ["coach", "me", "applications"] });
      qc.invalidateQueries({ queryKey: ["coach-facilities"] });
      toast({ title: "Paraiška pateikta" });
      setApplyOpen(false);
      setApplyFacilityId(null);
      setApplyMessage("");
      setFacilityFilter("");
    },
    onError: (e: Error) => {
      toast({ title: "Klaida", description: e.message, variant: "destructive" });
    },
  });

  // Facility ids the coach already has a relationship with (pending or approved) — hide from picker
  const usedFacilityIds = useMemo(() => {
    const set = new Set<number>();
    (facilitiesQ.data ?? []).forEach(f => { if (f.facilityId) set.add(f.facilityId); });
    (applicationsQ.data ?? []).forEach(a => { if (a.status === "pending" && a.facilityId) set.add(a.facilityId); });
    return set;
  }, [facilitiesQ.data, applicationsQ.data]);

  const pendingApplications = (applicationsQ.data ?? []).filter(a => a.status === "pending");
  // Group pending by facility (one row per facility, not per court)
  const pendingByFacility = useMemo(() => {
    const map = new Map<string, CoachApplication & { courtNames: string[] }>();
    for (const a of pendingApplications) {
      const key = a.facilityId != null ? `f${a.facilityId}` : `c${a.courtId}`;
      if (!map.has(key)) {
        map.set(key, { ...a, courtNames: [a.courtName] });
      } else {
        map.get(key)!.courtNames.push(a.courtName);
      }
    }
    return Array.from(map.values());
  }, [pendingApplications]);

  const filteredFacilityOptions = (allFacilitiesQ.data ?? []).filter(f => {
    if (usedFacilityIds.has(f.id)) return false;
    if (!facilityFilter.trim()) return true;
    const q = facilityFilter.toLowerCase();
    return f.name.toLowerCase().includes(q) || (f.city ?? "").toLowerCase().includes(q);
  });

  const [editing, setEditing] = useState(false);
  const [form, setForm] = useState<Partial<Omit<Coach, 'pricePerHour'> & { pricePerHour?: string }>>({});

  // ─── Services CRUD (Phase 4) ─────────────────────────────────────────────
  const [serviceDialogOpen, setServiceDialogOpen] = useState(false);
  const [editingServiceId, setEditingServiceId] = useState<number | null>(null);
  const [pendingDeleteServiceId, setPendingDeleteServiceId] = useState<number | null>(null);

  const serviceForm = useForm<ServiceFormValues>({
    resolver: zodResolver(serviceFormSchema),
    defaultValues: {
      name: "",
      description: "",
      sport: "",
      durationMin: "60",
      priceEur: "",
      maxParticipants: "1",
      audienceLevel: "",
      courtBinding: COURT_ANY_VALUE,
      isActive: true,
    },
  });

  // Flatten the coach's approved court ids → friendly labels for the Court
  // Select. We pull from facilitiesQ (which is the same source the public
  // "Treniruoja čia" panel uses) so the picker can never offer a court the
  // coach isn't approved at — matches the assertCoachOwnsCourt server check.
  const approvedCourtOptions = useMemo(() => {
    const out: Array<{ id: number; label: string }> = [];
    for (const f of facilitiesQ.data ?? []) {
      for (const c of f.courts) {
        const facilityBit = f.facilityName ? ` · ${f.facilityName}` : "";
        out.push({ id: c.id, label: `${c.name}${facilityBit}` });
      }
    }
    return out;
  }, [facilitiesQ.data]);

  // Same invalidation block fires on every services mutation — keeps the
  // public profile, owner panel, AND marketplace list in sync (Invariant A
  // — pricePerHour is denormalized server-side, so the cards refetch).
  function invalidateAfterServiceMutation() {
    qc.invalidateQueries({ queryKey: ["coach-services", coachId] });
    qc.invalidateQueries({ queryKey: ["coach"] });            // ["coach", id] + ["coach", "me"]
    qc.invalidateQueries({ queryKey: ["coaches"] });          // marketplace
  }

  const createServiceMut = useMutation({
    mutationFn: async (values: ServiceFormValues) => {
      if (!coachId) throw new Error("Trūksta trenerio ID");
      const r = await fetch(`${API}/coaches/${coachId}/services`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({
          name: values.name,
          description: values.description.trim() || null,
          sport: values.sport,
          durationMin: parseInt(values.durationMin, 10),
          priceCents: priceEurToCents(values.priceEur),
          maxParticipants: parseInt(values.maxParticipants, 10),
          audienceLevel: values.audienceLevel || null,
          courtId: values.courtBinding === COURT_ANY_VALUE ? null : parseInt(values.courtBinding, 10),
          isActive: values.isActive,
        }),
      });
      if (!r.ok) {
        const err = await r.json().catch(() => ({}));
        throw new Error(err.message ?? err.error ?? "Nepavyko sukurti paslaugos");
      }
      return r.json();
    },
    onSuccess: () => {
      invalidateAfterServiceMutation();
      toast({ title: "Paslauga sukurta" });
      setServiceDialogOpen(false);
      setEditingServiceId(null);
      serviceForm.reset();
    },
    onError: (e: Error) => {
      toast({ title: "Klaida", description: e.message, variant: "destructive" });
    },
  });

  const updateServiceMut = useMutation({
    mutationFn: async ({ serviceId, values }: { serviceId: number; values: ServiceFormValues }) => {
      if (!coachId) throw new Error("Trūksta trenerio ID");
      const r = await fetch(`${API}/coaches/${coachId}/services/${serviceId}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({
          name: values.name,
          description: values.description.trim() || null,
          sport: values.sport,
          durationMin: parseInt(values.durationMin, 10),
          priceCents: priceEurToCents(values.priceEur),
          maxParticipants: parseInt(values.maxParticipants, 10),
          audienceLevel: values.audienceLevel || null,
          courtId: values.courtBinding === COURT_ANY_VALUE ? null : parseInt(values.courtBinding, 10),
          isActive: values.isActive,
        }),
      });
      if (!r.ok) {
        const err = await r.json().catch(() => ({}));
        throw new Error(err.message ?? err.error ?? "Nepavyko atnaujinti");
      }
      return r.json();
    },
    onSuccess: () => {
      invalidateAfterServiceMutation();
      toast({ title: "Paslauga atnaujinta" });
      setServiceDialogOpen(false);
      setEditingServiceId(null);
      serviceForm.reset();
    },
    onError: (e: Error) => {
      toast({ title: "Klaida", description: e.message, variant: "destructive" });
    },
  });

  const deleteServiceMut = useMutation({
    mutationFn: async (serviceId: number) => {
      if (!coachId) throw new Error("Trūksta trenerio ID");
      const r = await fetch(`${API}/coaches/${coachId}/services/${serviceId}`, {
        method: "DELETE",
        credentials: "include",
      });
      if (!r.ok) {
        const err = await r.json().catch(() => ({}));
        throw new Error(err.message ?? err.error ?? "Nepavyko ištrinti");
      }
      return r.json() as Promise<{ deleted: boolean; deactivated: boolean }>;
    },
    onSuccess: (result) => {
      invalidateAfterServiceMutation();
      toast({
        title: result.deactivated ? "Paslauga sustabdyta" : "Paslauga pašalinta",
        description: result.deactivated
          ? "Ji buvo susieta su rezervacijomis, todėl liko istorijoje."
          : undefined,
      });
      setPendingDeleteServiceId(null);
    },
    onError: (e: Error) => {
      toast({ title: "Klaida", description: e.message, variant: "destructive" });
      setPendingDeleteServiceId(null);
    },
  });

  function openServiceCreate() {
    setEditingServiceId(null);
    serviceForm.reset({
      name: "",
      description: "",
      // Default to first sport so the Select renders with a value.
      sport: (coach?.sports ?? [])[0] ?? "",
      durationMin: "60",
      priceEur: "",
      maxParticipants: "1",
      audienceLevel: "",
      courtBinding: COURT_ANY_VALUE,
      isActive: true,
    });
    setServiceDialogOpen(true);
  }

  function openServiceEdit(svc: CoachService) {
    setEditingServiceId(svc.id);
    serviceForm.reset({
      name: svc.name,
      description: svc.description ?? "",
      sport: svc.sport,
      durationMin: String(svc.durationMin),
      priceEur: centsToEuroString(svc.priceCents),
      maxParticipants: String(svc.maxParticipants),
      audienceLevel: svc.audienceLevel ?? "",
      courtBinding: svc.courtId == null ? COURT_ANY_VALUE : String(svc.courtId),
      isActive: svc.isActive,
    });
    setServiceDialogOpen(true);
  }

  function submitServiceForm(values: ServiceFormValues) {
    if (editingServiceId != null) {
      updateServiceMut.mutate({ serviceId: editingServiceId, values });
    } else {
      createServiceMut.mutate(values);
    }
  }

  useEffect(() => {
    if (coach) {
      setForm({
        name: coach.name,
        email: coach.email,
        bio: coach.bio ?? "",
        photoUrl: coach.photoUrl ?? "",
        videoUrl: coach.videoUrl ?? "",
        pricePerHour: coach.pricePerHour != null ? centsToEuroString(coach.pricePerHour) : "",
        sports: coach.sports ?? [],
        availabilityDescription: coach.availabilityDescription ?? "",
        phone: coach.phone ?? "",
      });
    } else if (isOwnProfileRoute && user && !coach) {
      setForm({
        name: user.fullName ?? "",
        email: user.primaryEmailAddress?.emailAddress ?? "",
        sports: [],
      });
      setEditing(true);
    }
  }, [coach, isOwnProfileRoute, user]);

  const saveMutation = useMutation({
    mutationFn: async (data: typeof form) => {
      const emailErr = validateEmail(data.email);
      if (emailErr) throw new Error(emailErr);
      const phoneErr = validatePhone(data.phone, { required: false });
      if (phoneErr) throw new Error(phoneErr);
      const url = isOwnProfileRoute ? `${API}/coaches/me` : `${API}/coaches/${coach!.id}`;
      const r = await fetch(url, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({
          ...data,
          pricePerHour: euroStringToCents(data.pricePerHour as string | null | undefined),
        }),
      });
      if (!r.ok) {
        const err = await r.json().catch(() => ({}));
        throw new Error(err.error ?? "Failed to save");
      }
      return r.json();
    },
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ["coach"] });
      qc.invalidateQueries({ queryKey: ["coaches"] });
      toast({ title: "Profilis išsaugotas" });
      setEditing(false);
    },
    onError: (e: Error) => {
      toast({ title: "Klaida", description: e.message, variant: "destructive" });
    },
  });

  const toggleSport = (sport: string) => {
    setForm(f => ({
      ...f,
      sports: (f.sports ?? []).includes(sport)
        ? (f.sports ?? []).filter(s => s !== sport)
        : [...(f.sports ?? []), sport],
    }));
  };

  if (isOwnProfileRoute && !isSignedIn) {
    return (
      <Layout>
        <div className="container mx-auto px-4 py-20 text-center text-muted-foreground">
          Prisijunkite, kad matytumėte trenerio profilį.
        </div>
      </Layout>
    );
  }

  if (isLoading) {
    return (
      <Layout>
        <div className="container mx-auto px-4 py-12 max-w-2xl space-y-6">
          <Skeleton className="h-40 w-full rounded-2xl" />
          <Skeleton className="h-60 w-full rounded-2xl" />
        </div>
      </Layout>
    );
  }

  if (!coach && !isOwnProfileRoute) {
    return (
      <Layout>
        <div className="container mx-auto px-4 py-20 text-center">
          <h1 className="text-2xl font-bold mb-3">Treneris nerastas</h1>
          <Link href="/coaches">
            <Button variant="outline" className="mt-4">Grįžti į sąrašą</Button>
          </Link>
        </div>
      </Layout>
    );
  }

  const displayCoach = editing ? null : coach;

  return (
    <Layout>
      <div className="container mx-auto px-4 py-12 max-w-2xl space-y-6">

        {/* Back link */}
        <BackButton to="/coaches" label="Visi treneriai" />

        {/* Header card */}
        <div className="bg-card border rounded-2xl p-6 shadow-sm">
          <div className="flex items-start justify-between gap-4">
            <div className="flex items-center gap-4">
              {displayCoach?.photoUrl ? (
                <img
                  src={displayCoach.photoUrl}
                  alt={displayCoach.name}
                  className="w-20 h-20 rounded-full object-cover border-2 border-primary/20 shrink-0"
                />
              ) : (
                <div className="w-20 h-20 rounded-full bg-primary/10 flex items-center justify-center shrink-0">
                  <User className="w-10 h-10 text-primary/60" />
                </div>
              )}
              <div>
                <h1 className="text-2xl font-bold">{displayCoach?.name ?? (isOwnProfileRoute ? "Trenerio profilis" : "")}</h1>
                {displayCoach?.email && (
                  <p className="text-sm text-muted-foreground flex items-center gap-1.5 mt-0.5">
                    <Mail className="w-3.5 h-3.5" />
                    {displayCoach.email}
                  </p>
                )}
                {displayCoach?.phone && (
                  <p className="text-sm text-muted-foreground flex items-center gap-1.5 mt-0.5">
                    <Phone className="w-3.5 h-3.5" />
                    {displayCoach.phone}
                  </p>
                )}
              </div>
            </div>
            {isOwn && !editing && (
              <Button size="sm" variant="outline" onClick={() => setEditing(true)}>
                <Edit2 className="w-4 h-4 mr-1.5" />
                Redaguoti
              </Button>
            )}
          </div>

          {displayCoach && (
            <div className="mt-5 space-y-4">
              {displayCoach.sports.length > 0 && (
                <div className="flex flex-wrap gap-2">
                  {displayCoach.sports.map(s => (
                    <SportPill key={s} sport={s} variant="subtle" />
                  ))}
                </div>
              )}

              <div className="flex flex-wrap gap-4 text-sm">
                {displayCoach.pricePerHour != null && (
                  <div className="flex items-center gap-1.5 text-foreground font-semibold">
                    <Euro className="w-4 h-4 text-primary" />
                    {centsToEuroString(displayCoach.pricePerHour)}€ / val
                  </div>
                )}
                {displayCoach.availabilityDescription && (
                  <div className="flex items-center gap-1.5 text-muted-foreground">
                    <Clock className="w-4 h-4" />
                    {displayCoach.availabilityDescription}
                  </div>
                )}
              </div>

              {displayCoach.bio && (
                <p className="text-sm text-muted-foreground leading-relaxed">{displayCoach.bio}</p>
              )}

              {displayCoach.videoUrl && (
                <a
                  href={displayCoach.videoUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="inline-flex items-center gap-2 text-sm text-primary hover:underline"
                >
                  <Video className="w-4 h-4" />
                  Peržiūrėti video
                </a>
              )}

            </div>
          )}
        </div>

        {/* Services — bookable lesson types. For non-owners we render only
            isActive services (the API enforces this). For the owner we show
            all rows + management controls. */}
        {!editing && coach && (
          <div className="bg-card border rounded-2xl p-6 shadow-sm">
            <div className="flex items-start justify-between gap-3 mb-4">
              <h2 className="text-base font-semibold flex items-center gap-2">
                <Sparkles className="w-4 h-4 text-primary" />
                {isOwn ? "Mano paslaugos" : "Paslaugos"}
              </h2>
              {isOwn && (() => {
                const total = (servicesQ.data ?? []).length;
                const atLimit = total >= SERVICE_CATALOG_LIMIT;
                return (
                  <div className="flex flex-col items-end gap-1 shrink-0">
                    <Button
                      size="sm"
                      onClick={openServiceCreate}
                      disabled={atLimit}
                      title={atLimit ? `Pasiektas paslaugų limitas (${SERVICE_CATALOG_LIMIT})` : undefined}
                    >
                      <Plus className="w-3.5 h-3.5 mr-1.5" />
                      Pridėti paslaugą
                    </Button>
                    <span className="text-[10px] text-muted-foreground tabular-nums">
                      {total}/{SERVICE_CATALOG_LIMIT}
                    </span>
                  </div>
                );
              })()}
            </div>

            {servicesQ.isLoading ? (
              <div className="space-y-3">
                <Skeleton className="h-24 w-full rounded-xl" />
                <Skeleton className="h-24 w-full rounded-xl" />
              </div>
            ) : (() => {
              const allServices = servicesQ.data ?? [];
              const visibleServices = isOwn ? allServices : allServices.filter(s => s.isActive);
              if (visibleServices.length === 0) {
                return (
                  <div className="text-sm text-muted-foreground py-8 text-center bg-muted/30 rounded-lg border border-dashed">
                    {isOwn
                      ? 'Dar neturite paslaugų. Paspauskite "Pridėti paslaugą", kad pridėtumėte pirmąją.'
                      : "Šiuo metu treneris neturi aktyvių paslaugų."}
                  </div>
                );
              }
              return (
                <div className="space-y-3">
                  {visibleServices.map(svc => (
                    <div
                      key={svc.id}
                      className={`border rounded-xl p-4 hover:border-primary/40 hover:shadow-sm transition-all bg-card ${
                        !svc.isActive ? "opacity-60" : ""
                      }`}
                    >
                      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-3">
                        {/* Left — name, sport pill, metadata */}
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 flex-wrap">
                            <h3 className="font-semibold text-sm md:text-base text-foreground">
                              {svc.name}
                            </h3>
                            <SportPill sport={svc.sport} variant="subtle" size="sm" />
                            {!svc.isActive && (
                              <Badge variant="outline" className="text-[10px] gap-1 border-muted-foreground/30 text-muted-foreground">
                                <PauseCircle className="w-3 h-3" />
                                Sustabdyta
                              </Badge>
                            )}
                          </div>
                          <div className="flex flex-wrap items-center gap-x-3 gap-y-1 mt-2 text-xs text-muted-foreground">
                            <span className="inline-flex items-center gap-1">
                              <Clock className="w-3.5 h-3.5" />
                              {formatDuration(svc.durationMin)}
                            </span>
                            {svc.maxParticipants > 1 && (
                              <span className="inline-flex items-center gap-1">
                                <Users className="w-3.5 h-3.5" />
                                Iki {svc.maxParticipants} asm.
                              </span>
                            )}
                            {svc.audienceLevel && AUDIENCE_LT[svc.audienceLevel] && (
                              <span className="inline-flex items-center gap-1">
                                <User className="w-3.5 h-3.5" />
                                {AUDIENCE_LT[svc.audienceLevel]}
                              </span>
                            )}
                          </div>
                          {svc.description && (
                            <p className="mt-2 text-xs text-muted-foreground leading-relaxed line-clamp-2">
                              {svc.description}
                            </p>
                          )}
                        </div>

                        {/* Right — price + CTA / owner controls. On mobile this
                            row sits below the name block; on md+ it floats
                            right. */}
                        <div className="flex items-center justify-between md:justify-end md:flex-col md:items-end gap-3 md:gap-2 shrink-0 pt-1 md:pt-0 md:min-w-[140px]">
                          <div className="text-lg md:text-xl font-bold tabular-nums text-foreground">
                            {centsToEuroString(svc.priceCents)}€
                          </div>
                          {isOwn ? (
                            <div className="flex items-center gap-1.5">
                              <Button
                                size="sm"
                                variant="outline"
                                onClick={() => openServiceEdit(svc)}
                                className="h-8 px-2"
                              >
                                <Edit2 className="w-3.5 h-3.5 md:mr-1.5" />
                                <span className="hidden md:inline">Redaguoti</span>
                              </Button>
                              <Button
                                size="sm"
                                variant="outline"
                                onClick={() => setPendingDeleteServiceId(svc.id)}
                                className="h-8 px-2 text-destructive hover:text-destructive"
                              >
                                <Trash2 className="w-3.5 h-3.5 md:mr-1.5" />
                                <span className="hidden md:inline">Ištrinti</span>
                              </Button>
                            </div>
                          ) : (
                            <Button
                              size="sm"
                              onClick={() => {
                                // Phase 5 will replace this with the slot-picker dialog.
                                console.log("Open booking modal for:", svc.id);
                              }}
                              className="w-auto"
                            >
                              <CalendarDays className="w-3.5 h-3.5 mr-1.5" />
                              Užsakyti
                            </Button>
                          )}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              );
            })()}
          </div>
        )}

        {/* Public facilities list — where this coach teaches */}
        {!editing && coach && (facilitiesQ.data?.length ?? 0) > 0 && (
          <div className="bg-card border rounded-2xl p-6 shadow-sm">
            <h2 className="text-base font-semibold mb-4 flex items-center gap-2">
              <Building2 className="w-4 h-4 text-primary" />
              {isOwn ? "Mano vietos" : "Treniruoja čia"}
            </h2>
            <div className="space-y-2">
              {facilitiesQ.data!.map((f, i) => (
                <div key={i} className="flex items-start gap-3 p-3 rounded-lg bg-muted/30 border">
                  <MapPin className="w-4 h-4 text-muted-foreground mt-0.5 shrink-0" />
                  <div className="flex-1 min-w-0">
                    <div className="font-medium text-sm">{f.facilityName}</div>
                    {(f.city || f.address) && (
                      <div className="text-xs text-muted-foreground mt-0.5">
                        {[f.city, f.address].filter(Boolean).join(" · ")}
                      </div>
                    )}
                    {f.courts.length > 0 && (
                      <div className="flex flex-wrap gap-1.5 mt-2">
                        {f.courts.map(c => (
                          <Link key={c.id} href={`/court/${c.id}`}>
                            <Badge variant="outline" className="cursor-pointer hover:bg-primary/10 text-[11px]">
                              {c.name}
                            </Badge>
                          </Link>
                        ))}
                      </div>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Mano vietos — pending applications + apply form (own profile only) */}
        {isOwn && !editing && coach && (
          <div className="bg-card border rounded-2xl p-6 shadow-sm space-y-5">
            <div className="flex items-center justify-between">
              <h2 className="text-base font-semibold flex items-center gap-2">
                <Send className="w-4 h-4 text-primary" />
                Paraiškos vietoms
              </h2>
              {!applyOpen && (
                <Button size="sm" variant="outline" onClick={() => setApplyOpen(true)}>
                  <Send className="w-4 h-4 mr-1.5" />
                  Pateikti paraišką
                </Button>
              )}
            </div>

            {/* Pending applications list */}
            {pendingByFacility.length > 0 && (
              <div className="space-y-2">
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Laukiama atsakymo</p>
                {pendingByFacility.map(p => (
                  <div key={p.invitationId} className="flex items-start justify-between gap-3 p-3 rounded-lg bg-amber-500/5 border border-amber-500/20">
                    <div className="flex items-start gap-2 min-w-0">
                      <Clock className="w-4 h-4 text-amber-600 mt-0.5 shrink-0" />
                      <div className="min-w-0">
                        <div className="font-medium text-sm">{p.facilityName ?? p.courtNames[0]}</div>
                        <div className="text-xs text-muted-foreground mt-0.5">
                          {p.courtNames.length} aikštelė(-ės) · pateikta {new Date(p.createdAt).toLocaleDateString("lt-LT")}
                        </div>
                      </div>
                    </div>
                    <Badge variant="outline" className="text-amber-700 border-amber-500/40 shrink-0">Laukia</Badge>
                  </div>
                ))}
              </div>
            )}

            {pendingByFacility.length === 0 && !applyOpen && (facilitiesQ.data?.length ?? 0) === 0 && (
              <p className="text-sm text-muted-foreground">
                Dar nesate pateikę nė vienos paraiškos. Pateikite paraišką vietai, kurioje norėtumėte treniruoti.
              </p>
            )}

            {/* Apply form */}
            {applyOpen && (
              <div className="space-y-3 pt-2 border-t">
                <div className="flex items-center justify-between">
                  <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Nauja paraiška</p>
                  <Button size="sm" variant="ghost" onClick={() => { setApplyOpen(false); setApplyFacilityId(null); setFacilityFilter(""); setApplyMessage(""); }}>
                    <X className="w-4 h-4" />
                  </Button>
                </div>

                <div className="relative">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                  <Input
                    placeholder="Ieškoti vietos pagal pavadinimą ar miestą..."
                    value={facilityFilter}
                    onChange={e => { setFacilityFilter(e.target.value); setApplyFacilityId(null); }}
                    className="pl-9"
                  />
                </div>

                {allFacilitiesQ.isLoading ? (
                  <Skeleton className="h-32 w-full rounded-lg" />
                ) : filteredFacilityOptions.length === 0 ? (
                  <p className="text-sm text-muted-foreground py-4 text-center">
                    {facilityFilter ? "Nieko nerasta." : "Visos vietos jau įtrauktos."}
                  </p>
                ) : (
                  <div className="max-h-56 overflow-y-auto border rounded-lg divide-y">
                    {filteredFacilityOptions.slice(0, 30).map(f => {
                      const selected = applyFacilityId === f.id;
                      return (
                        <button
                          key={f.id}
                          type="button"
                          onClick={() => setApplyFacilityId(f.id)}
                          className={`w-full text-left px-3 py-2.5 text-sm transition-colors flex items-start gap-2 ${
                            selected ? "bg-primary/10" : "hover:bg-muted/50"
                          }`}
                        >
                          <MapPin className="w-3.5 h-3.5 text-muted-foreground mt-0.5 shrink-0" />
                          <div className="flex-1 min-w-0">
                            <div className="font-medium truncate">{f.name}</div>
                            {f.city && <div className="text-xs text-muted-foreground truncate">{f.city}</div>}
                          </div>
                          {selected && <Check className="w-4 h-4 text-primary shrink-0" />}
                        </button>
                      );
                    })}
                  </div>
                )}

                <Textarea
                  placeholder="Žinutė savininkui (neprivaloma)"
                  value={applyMessage}
                  onChange={e => setApplyMessage(e.target.value)}
                  rows={3}
                />

                <Button
                  onClick={() => applyMut.mutate()}
                  disabled={!applyFacilityId || applyMut.isPending}
                  className="w-full"
                >
                  {applyMut.isPending ? "Siunčiama..." : (
                    <><Send className="w-4 h-4 mr-1.5" /> Pateikti paraišką</>
                  )}
                </Button>
              </div>
            )}
          </div>
        )}

        {/* Edit form */}
        {editing && (
          <div className="bg-card border rounded-2xl p-6 shadow-sm space-y-5">
            <div className="flex items-center justify-between">
              <h2 className="text-lg font-semibold">{coach ? "Redaguoti profilį" : "Sukurti trenerio profilį"}</h2>
              {coach && (
                <Button size="sm" variant="ghost" onClick={() => { setEditing(false); }}>
                  <X className="w-4 h-4" />
                </Button>
              )}
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Vardas *</label>
                <Input value={form.name ?? ""} onChange={e => setForm(f => ({ ...f, name: e.target.value }))} placeholder="Vardas Pavardė" />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-medium text-muted-foreground uppercase tracking-wider">El. paštas *</label>
                <Input value={form.email ?? ""} onChange={e => setForm(f => ({ ...f, email: e.target.value }))} placeholder="vardas@example.com" type="email" />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Telefonas</label>
                <Input value={form.phone ?? ""} onChange={e => setForm(f => ({ ...f, phone: e.target.value }))} placeholder="+370 600 00000" />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Kaina (€/val)</label>
                <Input
                  value={form.pricePerHour ?? ""}
                  onChange={e => setForm(f => ({ ...f, pricePerHour: e.target.value }))}
                  placeholder="30"
                  type="number" min="0"
                />
              </div>
              <div className="sm:col-span-2 space-y-1">
                <label className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Nuotraukos URL</label>
                <Input value={form.photoUrl ?? ""} onChange={e => setForm(f => ({ ...f, photoUrl: e.target.value }))} placeholder="https://..." />
              </div>
              <div className="sm:col-span-2 space-y-1">
                <label className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Video URL</label>
                <Input value={form.videoUrl ?? ""} onChange={e => setForm(f => ({ ...f, videoUrl: e.target.value }))} placeholder="https://youtube.com/..." />
              </div>
              <div className="sm:col-span-2 space-y-1">
                <label className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Aprašymas</label>
                <Textarea
                  value={form.bio ?? ""}
                  onChange={e => setForm(f => ({ ...f, bio: e.target.value }))}
                  placeholder="Papasakokite apie save, patirtį, treniravimo stilių..."
                  rows={4}
                />
              </div>
              <div className="sm:col-span-2 space-y-1">
                <label className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Darbo laikas</label>
                <Input
                  value={form.availabilityDescription ?? ""}
                  onChange={e => setForm(f => ({ ...f, availabilityDescription: e.target.value }))}
                  placeholder="Pn–Pt 09:00–21:00, Š 10:00–18:00"
                />
              </div>
            </div>

            {/* Sport selection */}
            <div className="space-y-2">
              <label className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Sporto šakos</label>
              <div className="flex flex-wrap gap-2">
                {SPORT_OPTIONS.map(sport => {
                  const active = (form.sports ?? []).includes(sport);
                  return (
                    <button
                      key={sport}
                      type="button"
                      onClick={() => toggleSport(sport)}
                      className="rounded-full transition-all"
                    >
                      <SportPill sport={sport} variant={active ? "solid" : "subtle"} size="sm" />
                    </button>
                  );
                })}
              </div>
            </div>

            <div className="flex gap-3 pt-2">
              <Button
                onClick={() => saveMutation.mutate(form)}
                disabled={saveMutation.isPending || !form.name || !form.email}
                className="flex-1"
              >
                {saveMutation.isPending ? "Saugoma..." : (
                  <><Check className="w-4 h-4 mr-1.5" /> Išsaugoti</>
                )}
              </Button>
              {coach && (
                <Button variant="outline" onClick={() => setEditing(false)}>
                  Atšaukti
                </Button>
              )}
            </div>
          </div>
        )}
      </div>

      {/* ─── Service upsert dialog ─────────────────────────────────────── */}
      <Dialog open={serviceDialogOpen} onOpenChange={(o) => {
        setServiceDialogOpen(o);
        if (!o) { setEditingServiceId(null); serviceForm.reset(); }
      }}>
        <DialogContent className="max-w-lg max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{editingServiceId == null ? "Pridėti paslaugą" : "Redaguoti paslaugą"}</DialogTitle>
            <DialogDescription>
              Paslauga atsiranda viešame profilyje ir paieškoje. Žemiausia kaina automatiškai tampa „pradedant nuo" rodikliu.
            </DialogDescription>
          </DialogHeader>

          <Form {...serviceForm}>
            <form
              onSubmit={serviceForm.handleSubmit(submitServiceForm)}
              className="space-y-4"
            >
              <FormField
                control={serviceForm.control}
                name="name"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Pavadinimas</FormLabel>
                    <FormControl>
                      <Input placeholder="Pvz. Individuali treniruotė" {...field} />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={serviceForm.control}
                name="description"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Aprašymas (nebūtina)</FormLabel>
                    <FormControl>
                      <Textarea
                        rows={3}
                        placeholder="Trumpas aprašymas, ką apima ši paslauga"
                        {...field}
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <FormField
                  control={serviceForm.control}
                  name="sport"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Sporto šaka</FormLabel>
                      <Select value={field.value} onValueChange={field.onChange}>
                        <FormControl>
                          <SelectTrigger>
                            <SelectValue placeholder="Pasirinkite" />
                          </SelectTrigger>
                        </FormControl>
                        <SelectContent>
                          {(coach?.sports ?? []).map((s) => (
                            <SelectItem key={s} value={s}>
                              {s}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={serviceForm.control}
                  name="durationMin"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Trukmė</FormLabel>
                      <Select value={field.value} onValueChange={field.onChange}>
                        <FormControl>
                          <SelectTrigger>
                            <SelectValue />
                          </SelectTrigger>
                        </FormControl>
                        <SelectContent>
                          {DURATION_OPTIONS.map((d) => (
                            <SelectItem key={d.value} value={d.value}>{d.label}</SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <FormField
                  control={serviceForm.control}
                  name="priceEur"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Kaina (€)</FormLabel>
                      <FormControl>
                        <Input
                          inputMode="decimal"
                          placeholder="35"
                          {...field}
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={serviceForm.control}
                  name="maxParticipants"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Maks. dalyvių</FormLabel>
                      <Select value={field.value} onValueChange={field.onChange}>
                        <FormControl>
                          <SelectTrigger>
                            <SelectValue />
                          </SelectTrigger>
                        </FormControl>
                        <SelectContent>
                          {[1, 2, 3, 4, 5, 6, 7, 8].map((n) => (
                            <SelectItem key={n} value={String(n)}>
                              {n === 1 ? "1 (individualus)" : `${n}`}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </div>

              <FormField
                control={serviceForm.control}
                name="audienceLevel"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Auditorija (nebūtina)</FormLabel>
                    <Select
                      value={field.value === "" ? AUDIENCE_NONE_VALUE : field.value}
                      onValueChange={(v) => field.onChange(v === AUDIENCE_NONE_VALUE ? "" : v)}
                    >
                      <FormControl>
                        <SelectTrigger>
                          <SelectValue placeholder="Visi" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        <SelectItem value={AUDIENCE_NONE_VALUE}>Visi (nenurodyta)</SelectItem>
                        {AUDIENCE_OPTIONS.map((a) => (
                          <SelectItem key={a.value} value={a.value}>{a.label}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={serviceForm.control}
                name="courtBinding"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Aikštelė</FormLabel>
                    <Select value={field.value} onValueChange={field.onChange}>
                      <FormControl>
                        <SelectTrigger>
                          <SelectValue />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        <SelectItem value={COURT_ANY_VALUE}>Bet kuri aikštelė (klientas pasirenka)</SelectItem>
                        {approvedCourtOptions.map((c) => (
                          <SelectItem key={c.id} value={String(c.id)}>{c.label}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={serviceForm.control}
                name="isActive"
                render={({ field }) => (
                  <FormItem className="flex items-center justify-between rounded-lg border p-3">
                    <div>
                      <FormLabel className="text-sm">Aktyvi</FormLabel>
                      <p className="text-xs text-muted-foreground mt-0.5">
                        Sustabdytos paslaugos lieka jūsų istorijoje, bet nematomos klientams.
                      </p>
                    </div>
                    <FormControl>
                      <Switch checked={field.value} onCheckedChange={field.onChange} />
                    </FormControl>
                  </FormItem>
                )}
              />

              <DialogFooter className="gap-2">
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => {
                    setServiceDialogOpen(false);
                    setEditingServiceId(null);
                    serviceForm.reset();
                  }}
                  disabled={createServiceMut.isPending || updateServiceMut.isPending}
                >
                  Atšaukti
                </Button>
                <Button
                  type="submit"
                  disabled={createServiceMut.isPending || updateServiceMut.isPending}
                >
                  {editingServiceId == null ? "Sukurti" : "Išsaugoti"}
                </Button>
              </DialogFooter>
            </form>
          </Form>
        </DialogContent>
      </Dialog>

      {/* ─── Delete confirmation ──────────────────────────────────────── */}
      <AlertDialog
        open={pendingDeleteServiceId != null}
        onOpenChange={(o) => { if (!o) setPendingDeleteServiceId(null); }}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Ištrinti paslaugą?</AlertDialogTitle>
            <AlertDialogDescription>
              Jeigu paslauga jau yra susieta su rezervacijomis, ji bus tik sustabdyta (klientai jos nebematys). Priešingu atveju ji bus visiškai pašalinta.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={deleteServiceMut.isPending}>Atšaukti</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => { if (pendingDeleteServiceId != null) deleteServiceMut.mutate(pendingDeleteServiceId); }}
              disabled={deleteServiceMut.isPending}
            >
              Ištrinti
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </Layout>
  );
}

content.content:
1	/**
2	 * Coach-bookings — booking creation for Motifind-style coach service flow.
3	 *
4	 * The student picks a service on a coach profile, picks a date + start time,
5	 * and (when the service is floating) picks one of the coach's affiliated
6	 * courts. This router validates the whole window against:
7	 *   1. The service: must be active. priceCents + durationMin come straight
8	 *      from the row (Invariant B — Historical Immutability: the client
9	 *      cannot send a price; once persisted, the booking's coachAmountCents
10	 *      is snapshotted and never recomputed).
11	 *   2. The coach: must be approved, accepting students, on the
12	 *      student_pays_court model, with active Stripe Connect, and free
13	 *      across the requested window (uses getCoachAvailability).
14	 *   3. The court: must be the service's bound court when present; otherwise
15	 *      must be one the coach is approved at. Must not have an overlapping
16	 *      booking. Court price is computed server-side from court_pricing
17	 *      with fallback to court.pricePerHour / 2 per 30-min slot.
18	 *
19	 * Endpoints:
20	 *   GET  /coach-bookings/quote — price breakdown preview (no insert)
21	 *   POST /coach-bookings       — creates a status='pending' booking row
22	 *                                that the existing /payments/create-checkout
23	 *                                flow then turns into a Stripe session
24	 */
25	import { Router, type IRouter } from "express";
26	import { and, eq, ne } from "drizzle-orm";
27	import { z } from "zod";
28	import { clerkClient } from "@clerk/express";
29	import {
30	  db,
31	  coachesTable,
32	  coachServicesTable,
33	  courtsTable,
34	  courtCoachesTable,
35	  bookingsTable,
36	  userProfilesTable,
37	} from "@workspace/db";
38	import { requireAuth, getCurrentUserId } from "../lib/auth";
39	import { getCoachAvailability } from "../lib/coach-availability";
40	import { resolvePriceForSlot } from "../lib/pricing";
41	import { generateManagementToken } from "./bookings";
42	
43	const router: IRouter = Router();
44	
45	const dateRe = /^\d{4}-\d{2}-\d{2}$/;
46	const timeRe = /^\d{2}:\d{2}$/;
47	const SLOT_MIN = 30;
48	
49	const quoteSchema = z.object({
50	  coachServiceId: z.coerce.number().int().positive(),
51	  courtId: z.coerce.number().int().positive().optional(),
52	  date: z.string().regex(dateRe, "Invalid date"),
53	  startTime: z.string().regex(timeRe, "Invalid time"),
54	});
55	
56	function addMinutes(hhmm: string, mins: number): string {
57	  const [h, m] = hhmm.split(":").map(Number);
58	  const total = h * 60 + m + mins;
59	  const hh = Math.floor(total / 60).toString().padStart(2, "0");
60	  const mm = (total % 60).toString().padStart(2, "0");
61	  return `${hh}:${mm}`;
62	}
63	
64	interface ResolvedWindow {
65	  service: typeof coachServicesTable.$inferSelect;
66	  coach: {
67	    id: number;
68	    userId: string;
69	  };
70	  court: { id: number; pricePerHour: string };
71	  startTime: string;
72	  endTime: string;
73	  durationMin: number;
74	  serviceCents: number;
75	  courtCents: number;
76	  totalCents: number;
77	}
78	
79	type ResolveError =
80	  | { status: 400; error: string }
81	  | { status: 404; error: string }
82	  | { status: 409; error: string }
83	  | { status: 422; error: string };
84	
85	/**
86	 * Shared validation pipeline used by both quote and create. Returns the
87	 * fully-resolved window or an error suitable for an HTTP response. Reads
88	 * every field server-side — the only inputs from the client are
89	 * (coachServiceId, courtId?, date, startTime).
90	 */
91	async function resolveCoachBookingWindow(input: {
92	  coachServiceId: number;
93	  courtId?: number;
94	  date: string;
95	  startTime: string;
96	}): Promise<{ ok: true; data: ResolvedWindow } | { ok: false; err: ResolveError }> {
97	  // 1. Service
98	  const [service] = await db
99	    .select()
100	    .from(coachServicesTable)
101	    .where(eq(coachServicesTable.id, input.coachServiceId));
102	  if (!service) return { ok: false, err: { status: 404, error: "Service not found" } };
103	  if (!service.isActive) {
104	    return { ok: false, err: { status: 422, error: "Service inactive" } };
105	  }
106	
107	  // 2. Coach
108	  const [coach] = await db
109	    .select({
110	      id: coachesTable.id,
111	      userId: coachesTable.userId,
112	      status: coachesTable.status,
113	      isAcceptingStudents: coachesTable.isAcceptingStudents,
114	      courtPaymentModel: coachesTable.courtPaymentModel,
115	    })
116	    .from(coachesTable)
117	    .where(eq(coachesTable.id, service.coachId));
118	  if (!coach) return { ok: false, err: { status: 404, error: "Coach not found" } };
119	  if (coach.status !== "approved") {
120	    return { ok: false, err: { status: 422, error: "Coach not approved" } };
121	  }
122	  if (!coach.isAcceptingStudents) {
123	    return { ok: false, err: { status: 422, error: "Coach not accepting students" } };
124	  }
125	  if (coach.courtPaymentModel !== "student_pays_court") {
126	    return { ok: false, err: { status: 422, error: "Coach payment model unsupported" } };
127	  }
128	
129	  // Coach Stripe Connect must be live — otherwise the post-payment transfer
130	  // for the coach's share would fail later, stranding funds on platform.
131	  const [coachProfile] = await db
132	    .select({ status: userProfilesTable.stripeAccountStatus })
133	    .from(userProfilesTable)
134	    .where(eq(userProfilesTable.userId, coach.userId));
135	  if (coachProfile?.status !== "active") {
136	    return { ok: false, err: { status: 422, error: "Coach Stripe account not active" } };
137	  }
138	
139	  // 3. Court selection
140	  let courtId: number;
141	  if (service.courtId != null) {
142	    // Court-bound service — server forces the court regardless of what the
143	    // client sent. Even sending a foreign id is silently overridden.
144	    courtId = service.courtId;
145	  } else {
146	    // Floating service — client MUST send a courtId and it must be one the
147	    // coach is approved at (assertCoachOwnsCourt-equivalent check).
148	    if (input.courtId == null) {
149	      return { ok: false, err: { status: 400, error: "courtId required for floating service" } };
150	    }
151	    const [aff] = await db
152	      .select({ id: courtCoachesTable.id })
153	      .from(courtCoachesTable)
154	      .where(and(
155	        eq(courtCoachesTable.coachId, coach.id),
156	        eq(courtCoachesTable.courtId, input.courtId),
157	      ));
158	    if (!aff) {
159	      return { ok: false, err: { status: 422, error: "Coach not affiliated with this court" } };
160	    }
161	    courtId = input.courtId;
162	  }
163	
164	  const [court] = await db
165	    .select({ id: courtsTable.id, pricePerHour: courtsTable.pricePerHour })
166	    .from(courtsTable)
167	    .where(eq(courtsTable.id, courtId));
168	  if (!court) return { ok: false, err: { status: 404, error: "Court not found" } };
169	
170	  // 4. Window
171	  const durationMin = service.durationMin;
172	  const startTime = input.startTime;
173	  if (durationMin % SLOT_MIN !== 0) {
174	    return { ok: false, err: { status: 400, error: "Service duration must be a multiple of 30 minutes" } };
175	  }
176	  const endTime = addMinutes(startTime, durationMin);
177	  // Sanity: end time must be later than start; only same-day windows.
178	  if (endTime <= startTime) {
179	    return { ok: false, err: { status: 400, error: "Booking window crosses midnight" } };
180	  }
181	
182	  // 5. Coach matrix check — every 30-min slot in [start, end) must be in the
183	  // coach's free-slot set. getCoachAvailability already subtracts existing
184	  // coach bookings, blocks, and weekly schedule gaps.
185	  const coachSlots = await getCoachAvailability(coach.id, input.date);
186	  const freeLabels = new Set(coachSlots.map(s => s.label));
187	  let cursor = startTime;
188	  while (cursor < endTime) {
189	    if (!freeLabels.has(cursor)) {
190	      return { ok: false, err: { status: 409, error: "Coach unavailable for this window" } };
191	    }
192	    cursor = addMinutes(cursor, SLOT_MIN);
193	  }
194	
195	  // 6. Court availability — string-overlap check on bookings for this court
196	  // on this date. Status != cancelled blocks the slot.
197	  const courtBookings = await db
198	    .select({ startTime: bookingsTable.startTime, endTime: bookingsTable.endTime })
199	    .from(bookingsTable)
200	    .where(and(
201	      eq(bookingsTable.courtId, courtId),
202	      eq(bookingsTable.date, input.date),
203	      ne(bookingsTable.status, "cancelled"),
204	    ));
205	  for (const b of courtBookings) {
206	    if (b.startTime < endTime && b.endTime > startTime) {
207	      return { ok: false, err: { status: 409, error: "Court already booked for this window" } };
208	    }
209	  }
210	
211	  // 7. Court price — walk 30-min slots, sum resolvePriceForSlot (EUR per
212	  // slot) so per-hour overrides and holiday rules apply. Fallback: half
213	  // the court's pricePerHour per 30-min slot.
214	  const defaultSlotPrice = Number(court.pricePerHour) / 2;
215	  let courtEurTotal = 0;
216	  cursor = startTime;
217	  while (cursor < endTime) {
218	    const slotEur = await resolvePriceForSlot(courtId, input.date, cursor, defaultSlotPrice);
219	    courtEurTotal += slotEur;
220	    cursor = addMinutes(cursor, SLOT_MIN);
221	  }
222	  const courtCents = Math.round(courtEurTotal * 100);
223	
224	  // 8. Service price is snapshotted from the row — Invariant B. The client
225	  // never sends a price; the booking's coachAmountCents is locked to this
226	  // value at insertion time and never re-derived from coachServicesTable
227	  // afterwards (even if the service price changes).
228	  const serviceCents = service.priceCents;
229	  const totalCents = courtCents + serviceCents;
230	
231	  return {
232	    ok: true,
233	    data: {
234	      service,
235	      coach,
236	      court,
237	      startTime,
238	      endTime,
239	      durationMin,
240	      serviceCents,
241	      courtCents,
242	      totalCents,
243	    },
244	  };
245	}
246	
247	// ─── GET /coach-bookings/quote ────────────────────────────────────────────
248	
249	router.get("/coach-bookings/quote", requireAuth, async (req, res): Promise<void> => {
250	  const parsed = quoteSchema.safeParse(req.query);
251	  if (!parsed.success) {
252	    res.status(400).json({ error: parsed.error.message });
253	    return;
254	  }
255	  const r = await resolveCoachBookingWindow(parsed.data);
256	  if (!r.ok) {
257	    res.status(r.err.status).json({ error: r.err.error });
258	    return;
259	  }
260	  const { data } = r;
261	  res.json({
262	    courtId: data.court.id,
263	    startTime: data.startTime,
264	    endTime: data.endTime,
265	    durationMin: data.durationMin,
266	    courtCents: data.courtCents,
267	    serviceCents: data.serviceCents,
268	    totalCents: data.totalCents,
269	  });
270	});
271	
272	// ─── POST /coach-bookings ─────────────────────────────────────────────────
273	
274	const createSchema = quoteSchema;
275	
276	router.post("/coach-bookings", requireAuth, async (req, res): Promise<void> => {
277	  const parsed = createSchema.safeParse(req.body);
278	  if (!parsed.success) {
279	    res.status(400).json({ error: parsed.error.message });
280	    return;
281	  }
282	  const callerId = getCurrentUserId(req);
283	  if (!callerId) {
284	    res.status(401).json({ error: "Unauthorized" });
285	    return;
286	  }
287	
288	  const r = await resolveCoachBookingWindow(parsed.data);
289	  if (!r.ok) {
290	    res.status(r.err.status).json({ error: r.err.error });
291	    return;
292	  }
293	  const { data } = r;
294	
295	  // Customer info — read from Clerk so the student doesn't have to retype
296	  // their name/email. Fallback: keep blank-ish defaults if Clerk lookup
297	  // fails so the booking can still proceed (we can surface a placeholder
298	  // 'Klientas' name in receipts).
299	  let customerName = "Klientas";
300	  let customerEmail = "";
301	  try {
302	    const u = await clerkClient.users.getUser(callerId);
303	    customerName = [u.firstName, u.lastName].filter(Boolean).join(" ").trim() || u.username || "Klientas";
304	    customerEmail = u.primaryEmailAddress?.emailAddress ?? "";
305	  } catch (err) {
306	    req.log?.warn?.({ err }, "Clerk lookup failed for coach-booking creator");
307	  }
308	
309	  // Insert the row. status='pending' so the existing cron sweeper will
310	  // reclaim it if the student abandons checkout. coachAmountCents is
311	  // snapshotted from service.priceCents (Invariant B). totalPrice is the
312	  // EUR string Stripe will charge (court + service).
313	  const [inserted] = await db
314	    .insert(bookingsTable)
315	    .values({
316	      courtId: data.court.id,
317	      bookerUserId: callerId,
318	      customerName,
319	      customerEmail,
320	      date: parsed.data.date,
321	      startTime: data.startTime,
322	      endTime: data.endTime,
323	      totalPrice: (data.totalCents / 100).toFixed(2),
324	      status: "pending",
325	      coachId: data.coach.userId,
326	      coachServiceId: data.service.id,
327	      coachAmountCents: data.serviceCents,
328	      // Authenticated booker → no guest management token needed.
329	      managementToken: null,
330	      isSplit: false,
331	    })
332	    .returning({ id: bookingsTable.id });
333	
334	  if (!inserted) {
335	    res.status(500).json({ error: "Failed to create booking" });
336	    return;
337	  }
338	
339	  res.status(201).json({
340	    bookingId: inserted.id,
341	    courtId: data.court.id,
342	    startTime: data.startTime,
343	    endTime: data.endTime,
344	    durationMin: data.durationMin,
345	    courtCents: data.courtCents,
346	    serviceCents: data.serviceCents,
347	    totalCents: data.totalCents,
348	  });
349	});
350	
351	// Re-export the generator so callers that pull from this module can use it
352	// without reaching into routes/bookings.ts directly.
353	export { generateManagementToken };
354	
355	export default router;
